/* ================= PORTAL POSMÉDICA · núcleo ================= */
/* Prototipo de demostración: usuarios, mensajes, comités y listas viven en el «libro institucional» (Excel) que se carga y descarga en este navegador. No hay servidor: la clave disuade, no protege como un sistema real. */
const PX={book:null,user:null,view:"login",ui:{},demo:false,dirty:false,last:Date.now(),mes:null};
const PSH={
 usr:["Usuarios",["ID","Usuario","Nombre","Cargo","Area","Rol","Programas","Sal","Hash","Activo","Registrado"]],
 msg:["Mensajes",["ID","Hilo","FechaHora","De","Para","Tipo","Prioridad","Asunto","Cuerpo","Paciente","Programa","Plazo","Estado","LeidoEn","LeidoPor","CerradoEn"]],
 com:["Comites",["ID","Nombre","Frecuencia","MesInicio","Norma","Responsable","Integrantes","Activo"]],
 cse:["ComiteSesiones",["ID","Comite","Periodo","Fecha","Acta","Enlace","Asistentes","Quorum","Estado","Nota","Usuario"]],
 cmp:["Compromisos",["ID","Comite","Sesion","Descripcion","Responsable","FechaLimite","Estado","FechaCierre","Evidencia","Usuario"]],
 doc:["Documentos",["ID","Codigo","Nombre","Tipo","Programas","Proceso","Version","FechaAprobacion","ProximaRevision","Estado","Enlace","Responsable","Fuente"]],
 lst:["ListasChequeo",["ID","Fecha","Turno","Programa","Lista","Lugar","Resultado","Cumplidos","Aplicables","Observador","Observacion","Usuario"]],
 man:["AportesManuales",["ID","Periodo","Matriz","Indicador","Programa","Numerador","Denominador","Nota","Usuario"]],
 prv:["ProaAuditoria",["ID","Fecha","Fuente","Ref","Programa","Paciente","Antimicrobiano","Restringido","Justificado","Autorizado","AcordeGuia","Reevaluado","DuracionConforme","Nota","Usuario"]],
 ram:["AlertasRAM",["ID","Fecha","Evento","Programa","Paciente","Microorganismo","Resistencia","Analizada","Conducta","Usuario"]],
 cal:["Calendario",["ID","Titulo","Tipo","Comite","Fecha","HoraInicio","HoraFin","Modalidad","Lugar","Enlace","Responsable","Invitados","Programa","Visibilidad","Descripcion","Estado","Respuestas","Serie","Nota","Creador","Registrado"]],
 prd:["Produccion",["ID","Fecha","Programa","EPS","Paciente","Actividad","CUPS","Cantidad","Nota","Usuario","Registrado","Anulado","MotivoAnulacion"]],
 rsp:["ReportesSP",["ID","Fecha","Programa","Paciente","Clasificacion","Categoria","Severidad","Descripcion","AccionInmediata","Analisis","PlanMejora","Responsable","Estado","FechaCierre","Usuario"]],
 log:["Bitacora",["FechaHora","Usuario","Accion","Hoja","Registro","Detalle"]],
 cfg:["Config",["Clave","Valor"]]
};
const PKEYS=Object.keys(PSH);
const PROGS=[
 {k:"nefro",n:"Nefroprotección",g:"mis",d:"Ruta de nefroprotección v7.2: valoración y grupo CAC, plan de intervenciones, agenda espejo, cohorte, vencidos e indicadores por EPS."},
 {k:"hd",n:"Hemodiálisis",g:"mis",d:"Turno con UF, valoración mensual, paraclínicos, vacunación VHB, acceso vascular, trasplante, calidad de diálisis e indicadores CAC."},
 {k:"dp",n:"Diálisis peritoneal",g:"mis",d:"Censo DP, entrenamiento, adecuación (Kt/V semanal), peritonitis e infecciones del orificio, visitas domiciliarias.",nx:"Mientras se construye: reporte aquí eventos de seguridad y los aportes mensuales a IAAS (peritonitis, IAAS-09)."},
 {k:"vih",n:"VIH",g:"mis",d:"Cohorte, agenda e inasistentes, laboratorios, TAR por grupo farmacológico, enfermería y carné de vacunación, historia clínica precargada, indicadores CAC y Nueva EPS, reportes y ruta GAO-PT-008."},
 {k:"ce",n:"Consulta externa",g:"mis",d:"Agenda, oportunidad de la cita, inasistencia y remisiones por especialidad."},
 {k:"qt",n:"Quimioterapia",g:"mis",d:"Agenda de infusión, esquemas, extravasación, reacciones infusionales y doble verificación de citostáticos."},
 {k:"lab",n:"Laboratorio clínico",g:"apo",d:"Solicitud mensual de los programas, muestras tomadas, carga de resultados y oportunidad. Hoy: hemodiálisis."},
 {k:"far",n:"Servicio farmacéutico",g:"apo",d:"Dispensación por programa, pendientes, farmacovigilancia y control de antimicrobianos restringidos.",nx:"Sin módulo por ahora: se definirá su alcance antes de construirlo. Mientras tanto, aportes a PROA y seguridad del paciente desde aquí."},
 {k:"sp",n:"Seguridad del paciente",g:"tra",d:"Reportes de todos los programas, análisis, planes de mejora y rondas de seguridad."},
 {k:"iaas",n:"IAAS",g:"tra",d:"Matriz GDC-MT-IAAS-001 alimentada por los programas y por las listas de chequeo (higiene de manos, técnica aséptica, desinfección)."},
 {k:"proa",n:"PROA",g:"tra",d:"Matriz GDC-MT-PROA-001: uso de antimicrobianos, auditoría prospectiva, restringidos y alertas de resistencia."},
 {k:"cal",n:"Calendario de actividades",g:"ges",d:"Reuniones, capacitaciones, comités, jornadas y visitas de la clínica, con responsable, invitados y confirmación de asistencia."},
 {k:"prod",n:"Producción asistencial",g:"ges",d:"Atenciones de todos los programas por mes y EPS; hemodiálisis se calcula del turno. Tarifas, valores y conciliación con clave."},
 {k:"sogcs",n:"SOGCS · Comités",g:"ges",d:"Comités institucionales según su frecuencia, actas, quórum y compromisos."},
 {k:"docs",n:"Documentos y guías",g:"ges",d:"Listado maestro de documentos de calidad y direccionamiento a guías de práctica clínica."},
 {k:"msg",n:"Mensajes",g:"ges",d:"Notificaciones formales entre usuarios y áreas, con acuse de lectura, plazo y respuesta."}
];
const PG={mis:"Programas misionales",apo:"Servicios de apoyo",tra:"Programas transversales",ges:"Gestión"};
const PROG=Object.fromEntries(PROGS.map(p=>[p.k,p]));
const PMIS=PROGS.filter(p=>p.g==="mis"||p.g==="apo").map(p=>p.k);
const PIC={cal:'<rect x="3.5" y="5" width="17" height="15" rx="2"/><path d="M3.5 10h17M8 3v4M16 3v4"/><path d="M8 14h3v3H8z"/>',nefro:'<path d="M9 4c-3 0-5 3-5 7s2 9 5 9 3-3 3-6-2-4-2-6 1-4-1-4z"/><path d="M15 4c3 0 5 3 5 7s-2 9-5 9"/>',hd:'<path d="M12 3s-6 7-6 11a6 6 0 0 0 12 0c0-4-6-11-6-11z"/>',dp:'<circle cx="12" cy="12" r="8"/><path d="M12 4v16M4 12h16"/>',vih:'<path d="M12 21s-7-4.5-7-10a4 4 0 0 1 7-2.6A4 4 0 0 1 19 11c0 5.5-7 10-7 10z"/>',ce:'<rect x="4" y="5" width="16" height="15" rx="2"/><path d="M8 3v4M16 3v4M4 10h16"/>',qt:'<path d="M10 3h4M12 3v4M8 7h8l-1 13H9z"/>',lab:'<path d="M9 3h6M10 3v6l-5 9a2 2 0 0 0 2 3h10a2 2 0 0 0 2-3l-5-9V3"/>',far:'<rect x="5" y="9" width="14" height="11" rx="2"/><path d="M8 9V6a4 4 0 0 1 8 0v3M12 12v5M9.5 14.5h5"/>',sp:'<path d="M12 3l8 3v6c0 5-3.5 8-8 9-4.5-1-8-4-8-9V6z"/><path d="M9 12l2 2 4-4"/>',iaas:'<circle cx="12" cy="12" r="4"/><path d="M12 2v4M12 18v4M2 12h4M18 12h4M5 5l3 3M16 16l3 3M5 19l3-3M16 8l3-3"/>',proa:'<rect x="3" y="9" width="18" height="6" rx="3" transform="rotate(-35 12 12)"/><path d="M9.5 8.5l5 7"/>',sogcs:'<rect x="4" y="4" width="16" height="16" rx="2"/><path d="M8 9h8M8 13h8M8 17h5"/>',docs:'<path d="M6 3h8l4 4v14H6z"/><path d="M14 3v4h4M9 12h6M9 16h6"/>',msg:'<path d="M4 5h16v11H8l-4 4z"/>'};
function pxIcon(k){return'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+(PIC[k]||"")+'</svg>';}

/* ---------- utilidades ---------- */
const pxNow=()=>nowTs();
const pxToday=()=>iso(TODAY());
const pxD=s=>s?(s instanceof Date?s:pdate(s)):null;
const pxFD=s=>{const d=pxD(s);return d?fd(d):"";};
const pxMes=()=>PX.mes||ym(addMonths(TODAY(),-1));
const pxMesTxt=m=>{const[a,b]=m.split("-");return["enero","febrero","marzo","abril","mayo","junio","julio","agosto","septiembre","octubre","noviembre","diciembre"][+b-1]+" de "+a;};
const PMESES=["Enero","Febrero","Marzo","Abril","Mayo","Junio","Julio","Agosto","Septiembre","Octubre","Noviembre","Diciembre"];
function pxNext(k,pre){let mx=0;PX.book[k].forEach(o=>{const m=/(\d+)$/.exec(o.ID||"");if(m)mx=Math.max(mx,+m[1]);});return pre+String(mx+1).padStart(5,"0");}
function pxLog(acc,k,id,det){PX.book.log.push({FechaHora:pxNow(),Usuario:PX.user?PX.user.Usuario:"",Accion:acc,Hoja:PSH[k]?PSH[k][0]:k,Registro:id||"",Detalle:det||""});}
function pxAdd(k,pre,o){const r=Object.assign({ID:pxNext(k,pre)},o);if(PSH[k][1].includes("Usuario")&&!r.Usuario&&k!=="usr")r.Usuario=PX.user?PX.user.Usuario:"";PX.book[k].push(r);pxLog("CREA",k,r.ID,"");PX.dirty=true;pxBookInfo();return r;}
function pxUpd(k,r,ch){Object.assign(r,ch);pxLog("MODIFICA",k,r.ID,Object.keys(ch).join(", "));PX.dirty=true;pxBookInfo();}
function pxCfg(k,def){const r=PX.book&&PX.book.cfg.find(x=>x.Clave===k);if(!r)return def;try{return JSON.parse(r.Valor);}catch(e){return r.Valor;}}
function pxSetCfg(k,v){let r=PX.book.cfg.find(x=>x.Clave===k);const s=JSON.stringify(v);if(r)r.Valor=s;else PX.book.cfg.push({Clave:k,Valor:s});PX.dirty=true;}
function pxNewBook(){const b={};PKEYS.forEach(k=>b[k]=[]);return b;}
const pxU=id=>PX.book.usr.find(u=>u.ID===id);
const pxUN=id=>{const u=pxU(id);return u?u.Nombre:id;};
const pxAreas=()=>[...new Set(PX.book.usr.filter(u=>u.Activo!=="NO").map(u=>u.Area).filter(Boolean))].sort();
const pxAdmin=()=>PX.user&&PX.user.Rol==="Administrador";
function pxCan(k){if(!PX.user)return false;if(pxAdmin())return true;if(k==="msg"||k==="docs"||k==="cal")return true;return String(PX.user.Programas||"").split(",").map(s=>s.trim()).includes(k);}
function pxHD(){return typeof ST!=="undefined"&&ST.book?ST.book:null;}

/* ---------- clave: PBKDF2-SHA256 ---------- */
const PX_IT=100000;
const pxB64=u=>btoa(String.fromCharCode(...new Uint8Array(u)));
async function pxHash(pw,salB64){const enc=new TextEncoder();const k=await crypto.subtle.importKey("raw",enc.encode(pw),"PBKDF2",false,["deriveBits"]);const salt=Uint8Array.from(atob(salB64),c=>c.charCodeAt(0));const bits=await crypto.subtle.deriveBits({name:"PBKDF2",hash:"SHA-256",salt,iterations:PX_IT},k,256);return pxB64(bits);}
async function pxSetPw(u,pw){const s=new Uint8Array(16);crypto.getRandomValues(s);u.Sal=pxB64(s);u.Hash=await pxHash(pw,u.Sal);}

/* ---------- libro institucional (Excel) ---------- */
function pxIsBook(wb){return wb.SheetNames.includes("Usuarios")&&wb.SheetNames.includes("Mensajes");}
function pxParse(wb){const b=pxNewBook();PKEYS.forEach(k=>{const ws=wb.Sheets[PSH[k][0]];if(!ws)return;b[k]=XLSX.utils.sheet_to_json(ws,{defval:"",raw:false}).map(r=>{const o={};PSH[k][1].forEach(c=>o[c]=r[c]==null?"":r[c]);return o;});});return b;}
function pxBuildWb(){const wb=XLSX.utils.book_new();PKEYS.forEach(k=>{const [n,cols]=PSH[k];const aoa=[cols].concat(PX.book[k].map(r=>cols.map(c=>r[c]==null?"":r[c])));XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet(aoa),n);});return wb;}
async function pxExportBook(){if(!PX.book)return;const ok=await saveWb(pxBuildWb(),"Libro_institucional_POSMEDICA_"+pxToday()+".xlsx");if(ok){PX.dirty=false;pxBookInfo();}}
async function pxExport(name,sheets){const wb=XLSX.utils.book_new();let n=0;sheets.forEach(([t,rows,cols])=>{n+=rows.length;XLSX.utils.book_append_sheet(wb,sheetFrom(rows,cols),t.slice(0,31));});if(!n){toast("No hay registros para exportar.");return;}await saveWb(wb,name);if(PX.book)pxLog("EXPORTA","log",name,"");}
function pxBookInfo(){const el=document.getElementById("pxbinfo");if(!el)return;el.textContent=PX.book?(PX.demo?"Demostración · ":"")+(PX.dirty?"cambios sin descargar":"sin cambios pendientes"):"";const b=document.getElementById("pxbexp");if(b)b.classList.toggle("warn",PX.dirty);}

/* ---------- vistas: arranque ---------- */
function pxPush(){if(!PX.user||PX.view==="login")return;PX.hist=PX.hist||[];PX.hist.push({v:PX.view,s:PX.ui.sub,hv:PX.view==="hd"?ST.view:null});if(PX.hist.length>40)PX.hist.shift();try{history.pushState({px:PX.hist.length},"");}catch(e){}}
function pxBack(){const h=(PX.hist||[]).pop();if(!h){pxGo("panel",null,true);return;}if(h.v==="hd")pxOpenHD(h.hv,true);else pxGo(h.v,h.s,true);}
function pxGo(v,sub,nb){if(PX.view==="prod"&&v!=="prod")pxProdLock("Valores de producción bloqueados al salir del módulo.");if(v==="hd"){pxOpenHD(null,nb);return;}if(v==="nefro"){pxOpenNefro(nb);return;}if(!nb&&!(v===PX.view&&(sub||null)===(PX.ui.sub||null)))pxPush();PX.view=v;if(sub!=null)PX.ui.sub=sub;else PX.ui.sub=null;document.getElementById("hdapp").hidden=true;document.getElementById("nefroapp").hidden=true;document.getElementById("pxmain").hidden=false;pxRender();window.scrollTo(0,0);}
function pxOpenHD(view,nb){if(!pxCan("hd")){toast("Su usuario no tiene acceso a Hemodiálisis.");return;}if(PX.view==="prod")pxProdLock();if(!nb&&PX.view!=="hd")pxPush();PX.view="hd";document.getElementById("pxmain").hidden=true;document.getElementById("nefroapp").hidden=true;document.getElementById("hdapp").hidden=false;
  ST.user=PX.user.Nombre+" · "+PX.user.Cargo;if(view)ST.view=view;syncBar();render();pxBar();window.scrollTo(0,0);}
function pxRender(){pxBar();const m=document.getElementById("pxmain");if(!PX.user){m.innerHTML=pxLogin();return;}
  try{m.innerHTML=({panel:pxPanel,cal:pxCal,msg:pxMsg,sogcs:pxSogcs,docs:pxDocs,sp:pxSP,iaas:pxIAAS,proa:pxPROA,usr:pxUsers,lab:pxLab,prod:pxProd,vih:vxView})[PX.view]?({panel:pxPanel,cal:pxCal,msg:pxMsg,sogcs:pxSogcs,docs:pxDocs,sp:pxSP,iaas:pxIAAS,proa:pxPROA,usr:pxUsers,lab:pxLab,prod:pxProd,vih:vxView})[PX.view]():pxProg(PX.view);}
  catch(e){console.error(e);m.innerHTML='<div class="alert bad"><p>Error al dibujar esta vista: '+esc(e.message)+'</p></div>';}}
function pxBar(){const b=document.getElementById("pxbar");if(!PX.user){b.hidden=true;return;}b.hidden=false;const un=pxUnread().length;const cur=PX.view==="panel"?"":(PROG[PX.view]?PROG[PX.view].n:PX.view==="usr"?"Usuarios":"");
  b.innerHTML='<div class="pxbar-in">'+(PX.view!=="panel"?'<button type="button" class="btn pxback" data-p="back" aria-label="Volver a la vista anterior"><svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M15 18l-6-6 6-6"/></svg>Atrás</button>':'')+'<button type="button" class="pxhome" data-p="go|panel" aria-label="Ir al panel" title="Ir al panel de programas"><img src="'+document.getElementById("pxlogo").src+'" alt=""><span><b>POSMÉDICA</b><small>Gestión clínica</small></span></button>'+(cur?'<span class="crumb"><button type="button" class="lnk" data-p="go|panel">Panel</button> / '+esc(cur)+'</span>':'')+
  '<div class="pxbar-r"><button type="button" class="btn sm" data-p="go|msg">Mensajes'+(un?' <span class="cnt">'+un+'</span>':'')+'</button><span class="who"><b>'+esc(PX.user.Nombre)+'</b><small>'+esc(PX.user.Cargo)+'</small></span><button type="button" class="btn sm" id="pxbexp" data-p="bookexp" title="Descargar el libro institucional con usuarios, mensajes, comités y listas">Descargar libro</button><button type="button" class="btn sm" data-p="logout">Salir</button></div></div><div class="pxbar-note"><span id="pxbinfo"></span></div>';pxBookInfo();}

function pxLogin(){
  const demo=PX.book&&PX.demo;const users=PX.book?PX.book.usr.filter(u=>u.Activo!=="NO"):[];
  return '<section class="pxcover"><div class="pxcover-l"><img id="pxlogo2" src="'+document.getElementById("pxlogo").src+'" alt="UNO-P Unidad Oncológica del Putumayo" class="pxlogo-big"><p class="eyebrow">POSMÉDICA GROUP S.A.S. · UNO-P · Mocoa, Putumayo</p><h1 class="pxt">Sistema de gestión clínica</h1><p class="pxlead">Un solo ingreso para los programas misionales, los servicios de apoyo, los programas transversales de seguridad del paciente, IAAS y PROA, los comités del SOGCS y los documentos de calidad.</p>'+pxPlatView(false)+
  '<div class="alert warn"><p><strong>Prototipo de demostración.</strong> Usuarios, mensajes y registros viven en el libro institucional que se carga en este navegador; no hay servidor. La clave de usuario disuade el acceso casual pero no reemplaza la seguridad de un sistema en servidor. No use datos reales de pacientes en esta etapa.</p></div></div>'+
  '<div class="pxcover-r panel">'+(PX.book?
   '<h3>Ingresar</h3><form id="pxlf" class="form1"><label class="f">Usuario<input type="text" id="pxlu" autocomplete="username" value="'+esc(PX.ui.lu||"")+'"></label><label class="f">Clave<input type="password" id="pxlp" autocomplete="current-password"></label><p class="note" id="pxlmsg" style="color:var(--bad)"></p><button type="submit" class="btn primary">Ingresar</button></form>'+
   (demo?'<div class="pxdemo"><p class="note">Usuarios de la demostración (clave <span class="mono">demo1234</span>). Cada uno ve los programas de su cargo.</p><div class="pxusers">'+users.map(u=>'<button type="button" class="pxuchip" data-p="pick|'+esc(u.Usuario)+'"><b>'+esc(u.Cargo)+'</b><small>'+esc(u.Usuario)+(u.Rol==="Administrador"?" · administrador":"")+'</small></button>').join("")+'</div></div>':'')+
   '<p class="note"><button type="button" class="lnk" data-p="unload">Cambiar de libro</button></p>'
  :'<h3>Abrir el sistema</h3><div class="form1"><button type="button" class="btn primary" data-p="demo">Entrar a la demostración</button><label class="btn" for="pxbookfile">Abrir libro institucional (.xlsx)</label><input type="file" id="pxbookfile" accept=".xlsx" hidden><button type="button" class="btn" data-p="newbook">Crear libro institucional nuevo</button></div><p class="note">La demostración carga usuarios, mensajes, comités y listas ficticios, y las cohortes ficticias de hemodiálisis y VIH.</p>')+
  '</div></section>';}
async function pxDoLogin(){const u=document.getElementById("pxlu").value.trim().toLowerCase(),p=document.getElementById("pxlp").value;const m=document.getElementById("pxlmsg");
  const r=PX.book.usr.find(x=>String(x.Usuario).toLowerCase()===u&&x.Activo!=="NO");if(!r||!p){m.textContent="Usuario o clave incorrectos.";return;}
  m.textContent="Verificando…";const h=await pxHash(p,r.Sal);if(h!==r.Hash){m.textContent="Usuario o clave incorrectos.";pxLog("INGRESO FALLIDO","usr",r.ID,"");return;}
  PX.user=r;PX.hist=[];PX.last=Date.now();pxLog("INGRESO","usr",r.ID,"");try{ST.user=r.Nombre+" · "+r.Cargo;}catch(e){}PX.view="panel";pxRender();toast("Bienvenido(a), "+r.Nombre+".");}
function pxLogout(msg){if(PX.user)pxLog("SALIDA","usr",PX.user.ID,msg||"");try{pxProdLock();}catch(e){}if(typeof finLock==="function"&&ST.fin&&ST.fin.key)try{finLock();}catch(e){}PX.user=null;PX.ui={};PX.view="login";pxNefroClose();document.getElementById("hdapp").hidden=true;document.getElementById("pxmain").hidden=false;pxRender();if(msg)toast(msg);}
function pxDlgNewBook(){openDlg("Crear libro institucional nuevo",'<p class="note">Se crea el primer usuario, con rol de administrador. Después podrá crear los demás usuarios en Usuarios.</p><div class="form"><label class="f">Nombre<input type="text" id="nb_n"></label><label class="f">Cargo<input type="text" id="nb_c" value="Coordinador asistencial"></label><label class="f">Usuario<input type="text" id="nb_u"></label><label class="f">Clave (mínimo 8 caracteres)<input type="password" id="nb_p"></label></div>',"Crear",()=>{
  const n=$("nb_n").value.trim(),c=$("nb_c").value.trim(),u=$("nb_u").value.trim().toLowerCase(),p=$("nb_p").value;if(n.length<3||u.length<3)return"Escriba nombre y usuario.";if(p.length<8)return"La clave debe tener al menos 8 caracteres.";
  PX.book=pxNewBook();PX.demo=false;const r={ID:"U-00001",Usuario:u,Nombre:n,Cargo:c,Area:"Coordinación asistencial",Rol:"Administrador",Programas:PROGS.map(x=>x.k).join(","),Activo:"SI",Registrado:pxNow()};PX.book.usr.push(r);
  pxSeedCatalogs();pxSetPw(r,p).then(()=>{PX.ui.lu=u;PX.dirty=true;pxRender();toast("Libro creado. Ingrese con su usuario y descárguelo para conservarlo.");});});}
function pxOnFile(f){if(!f)return;const rd=new FileReader();rd.onload=ev=>{try{const wb=XLSX.read(new Uint8Array(ev.target.result),{type:"array"});if(!pxIsBook(wb)){toast("Ese archivo no es un libro institucional (faltan las hojas Usuarios y Mensajes). El libro de hemodiálisis se abre dentro de Hemodiálisis.");return;}
  PX.book=pxParse(wb);PX.demo=false;PX.dirty=false;pxRender();toast("Libro institucional cargado: "+PX.book.usr.length+" usuarios.");}catch(e){console.error(e);toast("No se pudo leer el archivo: "+e.message);}};rd.readAsArrayBuffer(f);}

/* ---------- panel ---------- */
function pxPanel(){const u=PX.user;const g={};PROGS.forEach(p=>(g[p.g]=g[p.g]||[]).push(p));
  let h='<div class="mhead"><div><p class="eyebrow">'+esc(u.Area||"")+'</p><h2 class="mt">Panel de programas</h2><p class="note" style="margin:3px 0 0">'+esc(pxMesTxt(pxMes()))+'. Los programas sin acceso para su cargo aparecen atenuados.</p></div><label class="f" style="max-width:180px">Mes de seguimiento<input type="month" id="pxmes" value="'+pxMes()+'"></label></div>';
  h+=pxPlatView(true);const pend=pxPendientes();if(pend.length)h+='<div class="pxpend panel"><h3>Pendientes para usted</h3><ul>'+pend.map(x=>'<li><span class="st '+x.l+'">'+esc(x.t)+'</span> '+x.h+'</li>').join("")+'</ul></div>';
  Object.keys(PG).forEach(k=>{h+='<section class="pxgroup"><h3>'+PG[k]+'</h3><div class="pxcards">'+g[k].map(p=>pxCard(p)).join("")+'</div></section>';});
  return h;}
function pxCard(p){const can=pxCan(p.k);const k=pxKPI(p.k);const built=["nefro","hd","vih","sp","iaas","proa","sogcs","docs","msg","cal","lab","prod"].includes(p.k);
  return'<button type="button" class="pxcard'+(can?"":" off")+'" data-p="'+(can?"go|"+p.k:"noacc|"+p.k)+'"'+(can?"":' aria-disabled="true"')+'><span class="pxci">'+pxIcon(p.k)+'</span><span class="pxct"><b>'+esc(p.n)+'</b>'+'</span><span class="pxcd">'+esc(p.d)+'</span>'+'<span class="pxck">'+(built?'':'<span class="tag">en desarrollo</span>')+(k||'')+'</span>'+'</button>';}
function pxKPI(k){try{const H=pxHD();const m=pxMes();
  if(k==="hd"){if(!H)return'<span class="sd">Sin libro de hemodiálisis cargado</span>';ensureIdx();const act=H.pac.filter(p=>activeAt(p,ST.corte)).length;let al=0;try{al=alertas().total;}catch(e){}return'<span><b>'+act+'</b> activos</span><span class="'+(al?"bad":"")+'"><b>'+al+'</b> alertas</span>';}
  if(k==="cal"){const t=PX.book.cal.filter(e=>e.Fecha===pxToday()&&e.Estado!=="Cancelada"&&pxCalVisible(e)).length,p=pxCalPend().length;return'<span><b>'+t+'</b> hoy</span><span class="'+(p?"warn":"")+'"><b>'+p+'</b> invitaciones sin confirmar</span>';}
  if(k==="msg"){const n=pxUnread().length,v=pxVencidos().length;return'<span class="'+(n?"warn":"")+'"><b>'+n+'</b> sin leer</span><span class="'+(v?"bad":"")+'"><b>'+v+'</b> vencidos</span>';}
  if(k==="sogcs"){const c=pxComCump(ym(TODAY()).slice(0,4),ym(TODAY()));const cv=PX.book.cmp.filter(x=>pxCmpEst(x)==="Vencido").length;return'<span><b>'+(c.p?Math.round(c.r/c.p*100):"—")+' %</b> comités al día</span><span class="'+(cv?"bad":"")+'"><b>'+cv+'</b> compromisos vencidos</span>';}
  if(k==="docs"){const v=PX.book.doc.filter(d=>d.ProximaRevision&&d.ProximaRevision<pxToday()&&d.Estado==="Vigente").length;return'<span><b>'+PX.book.doc.length+'</b> documentos</span><span class="'+(v?"warn":"")+'"><b>'+v+'</b> con revisión vencida</span>';}
  if(k==="iaas"){const I=pxIAASCalc(m);const a=I.find(x=>x.id==="IAAS-02"),b=I.find(x=>x.id==="IAAS-04");return'<span>ITS-CVC <b>'+pxFmt(a)+'</b></span><span>Manos <b>'+pxFmt(b)+'</b></span>';}
  if(k==="proa"){const P=pxPROACalc(m);const a=P.find(x=>x.id==="IPROA-03");const pe=pxProaPend(m).length;return'<span>Restringidos <b>'+pxFmt(a)+'</b></span><span class="'+(pe?"warn":"")+'"><b>'+pe+'</b> sin auditar</span>';}
  if(k==="nefro")return pxNefroKPI();
  if(k==="vih"){if(!VX.book)return'<span class="sd">Sin libro VIH cargado</span>';const c=vxCorte();const A=vxPacs().filter(p=>vxSt(p,c).activo);const r=A.filter(p=>vxAlertas(p,c).nivel==="roja").length;return'<span><b>'+A.length+'</b> activos</span><span class="'+(r?"bad":"")+'"><b>'+r+'</b> en alerta roja</span>';}
  if(k==="lab"){if(!H)return'<span class="sd">Sin libro de hemodiálisis</span>';const P=pxLabPend().length;const nm=ym(addMonths(monthStart(TODAY()),1));const nx=solRecs(nm).length;return'<span class="'+(P?"warn":"")+'"><b>'+P+'</b> sin resultado</span><span>'+(nx?'<b>'+nx+'</b> solicitados para '+esc(nm):'solicitud de '+esc(nm)+' <b>sin generar</b>')+'</span>';}
  if(k==="prod"){const n=pxProdResumen(m).reduce((a,r)=>a+r.cant,0);return'<span><b>'+n.toLocaleString("es-CO")+'</b> atenciones en el mes</span>';}
  if(k==="sp"){const R=pxSPAll().filter(r=>r.Estado!=="Cerrado");return'<span class="'+(R.length?"warn":"")+'"><b>'+R.length+'</b> reportes abiertos</span>';}
  const d=PX.book.doc.filter(x=>String(x.Programas).split(",").includes(k)).length;return d?'<span><b>'+d+'</b> documentos</span>':"";}catch(e){console.error(e);return"";}}
function pxPendientes(){const L=[];const ch=pxCalHoy();if(ch.length)L.push({l:"info",t:"Hoy",h:ch.map(e=>esc((e.HoraInicio||"")+" "+e.Titulo)).join(" · ")+' · <button type="button" class="lnk" data-p="go|cal">ver calendario</button>'});const cp=pxCalPend();if(cp.length)L.push({l:"warn",t:"Invitaciones",h:cp.length+(cp.length===1?' actividad':' actividades')+' por confirmar asistencia · <button type="button" class="lnk" data-p="go|cal|agenda">confirmar</button>'});const un=pxUnread();if(un.length)L.push({l:"warn",t:"Mensajes",h:un.length+' sin leer · <button type="button" class="lnk" data-p="go|msg">abrir bandeja</button>'});
  const v=pxVencidos().filter(x=>pxMine(x));if(v.length)L.push({l:"bad",t:"Plazo vencido",h:v.length+(v.length===1?' notificación dirigida':' notificaciones dirigidas')+' a usted o su área sin respuesta'});
  const cm=PX.book.cmp.filter(x=>pxCmpEst(x)==="Vencido"&&(x.Responsable===PX.user.ID||x.Responsable===PX.user.Area));if(cm.length)L.push({l:"bad",t:"Compromisos",h:cm.length+' compromisos de comité vencidos a su cargo · <button type="button" class="lnk" data-p="go|sogcs|cmp">ver</button>'});
  if(pxCan("iaas")||pxCan("sp")){const t=pxToday();const tur=["Mañana","Tarde"].filter(j=>!PX.book.lst.some(x=>x.Lista==="des"&&x.Fecha===t&&x.Turno===j));if(tur.length&&new Date().getDay()!==0)L.push({l:"warn",t:"Desinfección",h:'Sin registro de desinfección entre turnos hoy: '+tur.join(" y ")+' · <button type="button" class="lnk" data-p="lst|des">registrar</button>'});}
  return L;}

/* ---------- programa en desarrollo ---------- */
function pxProg(k){const p=PROG[k];if(!p)return'<div class="panel empty">Vista no encontrada.</div>';
  let h='<div class="mhead"><div><p class="eyebrow">'+PG[p.g]+'</p><h2 class="mt">'+esc(p.n)+'</h2><p class="note" style="margin:3px 0 0">'+esc(p.d)+'</p></div></div>';
  h+='<div class="alert info"><p><strong>Módulo en desarrollo.</strong> '+esc(p.nx||"Se construirá con el mismo formato de Hemodiálisis.")+'</p></div>';
  h+='<div class="pxcols"><div class="panel"><h3>Aportes a los programas transversales</h3><p class="note">Mientras el módulo no exista, el programa alimenta a Seguridad del paciente, IAAS y PROA desde aquí.</p><div class="copyrow"><button type="button" class="btn primary" data-p="spnew|'+k+'">Reportar evento de seguridad</button><button type="button" class="btn" data-p="mannew|'+k+'">Aporte mensual a IAAS o PROA</button><button type="button" class="btn" data-p="lst|ron|'+k+'">Ronda de seguridad</button><button type="button" class="btn" data-p="lst|hm|'+k+'">Higiene de manos</button></div>'+
    '</div>'+
   '<div class="panel"><h3>Mensajes del programa</h3>'+pxMsgList(PX.book.msg.filter(m=>m.Programa===k&&m.Hilo===m.ID).slice(-6).reverse(),true)+'<button type="button" class="btn sm" data-p="compose|'+k+'">Nueva notificación</button></div></div>';
  h+=pxDocsTable(PX.book.doc.filter(d=>String(d.Programas).split(",").includes(k)),"Documentos del programa");
  return h;}

/* ---------- usuarios (administrador) ---------- */
function pxUsers(){if(!pxAdmin())return'<div class="panel empty">Solo el administrador gestiona usuarios.</div>';
  return'<div class="mhead"><div><h2 class="mt">Usuarios</h2><p class="note" style="margin:3px 0 0">Cada persona entra con su usuario. Los permisos se dan por programa. Las claves se guardan como derivación PBKDF2, nunca en texto.</p></div><div class="copyrow"><button type="button" class="btn primary" data-p="unew">Nuevo usuario</button></div></div>'+
  '<div class="panel tablebox" style="padding:0"><table><thead><tr><th>Usuario</th><th>Nombre y cargo</th><th>Área</th><th>Rol</th><th>Programas</th><th>Estado</th><th></th></tr></thead><tbody>'+PX.book.usr.map(u=>'<tr><td class="mono">'+esc(u.Usuario)+'</td><td><strong>'+esc(u.Nombre)+'</strong><span class="sub">'+esc(u.Cargo)+'</span></td><td>'+esc(u.Area)+'</td><td>'+esc(u.Rol)+'</td><td style="font-size:12.5px">'+esc(u.Rol==="Administrador"?"Todos":String(u.Programas).split(",").map(k=>PROG[k]?PROG[k].n:k).join(", "))+'</td><td>'+(u.Activo==="NO"?'<span class="st bad">Inactivo</span>':'<span class="st ok">Activo</span>')+'</td><td><button type="button" class="btn sm" data-p="uedit|'+u.ID+'">Editar</button></td></tr>').join("")+'</tbody></table></div>'+
  '<div class="panel"><h3>Bitácora de ingresos (últimos 15)</h3>'+(PX.book.log.filter(l=>/INGRESO|SALIDA/.test(l.Accion)).slice(-15).reverse().map(l=>'<div class="note mono">'+esc(l.FechaHora)+' · '+esc(l.Usuario)+' · '+esc(l.Accion)+(l.Detalle?' · '+esc(l.Detalle):'')+'</div>').join("")||'<p class="note">Sin registros.</p>')+'</div>';}
function pxDlgUser(id){const u=id?pxU(id):null;const pr=u?String(u.Programas).split(","):[];
  openDlg(u?"Editar usuario "+u.Usuario:"Nuevo usuario",'<div class="form"><label class="f">Nombre<input type="text" id="us_n" value="'+esc(u?u.Nombre:"")+'"></label><label class="f">Cargo<input type="text" id="us_c" value="'+esc(u?u.Cargo:"")+'"></label><label class="f">Área (para mensajes)<input type="text" id="us_a" list="us_al" value="'+esc(u?u.Area:"")+'"><datalist id="us_al">'+pxAreas().map(a=>'<option value="'+esc(a)+'">').join("")+'</datalist></label><label class="f">Usuario<input type="text" id="us_u" value="'+esc(u?u.Usuario:"")+'"'+(u?" disabled":"")+'></label><label class="f">Rol<select id="us_r">'+opt(["Estándar","Administrador"],u?u.Rol:"Estándar")+'</select></label><label class="f">'+(u?"Nueva clave (vacío = no cambia)":"Clave (mínimo 8)")+'<input type="password" id="us_p"></label>'+(u?'<label class="f">Estado<select id="us_e">'+opt([["SI","Activo"],["NO","Inactivo"]],u.Activo||"SI")+'</select></label>':'')+'</div><fieldset class="pxfs"><legend>Programas a los que accede</legend><div class="cols2">'+PROGS.filter(p=>!["msg","docs","cal"].includes(p.k)).map(p=>'<label class="chk"><input type="checkbox" data-uprog="'+p.k+'"'+(pr.includes(p.k)?" checked":"")+'> '+esc(p.n)+'</label>').join("")+'</div><p class="note">Mensajes, Documentos y Calendario están abiertos para todos los usuarios.</p></fieldset>',"Guardar",()=>{
   const o={Nombre:$("us_n").value.trim(),Cargo:$("us_c").value.trim(),Area:$("us_a").value.trim(),Rol:$("us_r").value,Programas:[...document.querySelectorAll("[data-uprog]:checked")].map(x=>x.dataset.uprog).join(",")};const p=$("us_p").value;
   if(o.Nombre.length<3||!o.Cargo||!o.Area)return"Complete nombre, cargo y área.";
   if(!u){const us=$("us_u").value.trim().toLowerCase();if(us.length<3)return"Escriba el usuario.";if(PX.book.usr.some(x=>String(x.Usuario).toLowerCase()===us))return"Ese usuario ya existe.";if(p.length<8)return"La clave debe tener al menos 8 caracteres.";
     const r=pxAdd("usr","U-",Object.assign(o,{Usuario:us,Activo:"SI",Registrado:pxNow()}));pxSetPw(r,p).then(()=>{pxRender();toast("Usuario "+us+" creado.");});return;}
   if(p&&p.length<8)return"La clave debe tener al menos 8 caracteres.";o.Activo=$("us_e").value;if(u.ID===PX.user.ID&&(o.Activo==="NO"||o.Rol!=="Administrador"))return"No puede quitarse a sí mismo el rol de administrador ni desactivarse.";
   pxUpd("usr",u,o);if(p)pxSetPw(u,p).then(()=>toast("Clave actualizada."));pxRender();toast("Usuario actualizado.");});}

/* ================= mensajes, documentos y SOGCS ================= */
const MSG_TIPO=["Notificación formal","Citación","Solicitud","Interconsulta administrativa","Alerta","Información"];
const MSG_PRI=["Rutina","Prioritaria","Urgente"];
const MSG_TPL=[
 {n:"Inasistencia a hemodiálisis → Trabajo social",para:"a:Trabajo social",tipo:"Notificación formal",pri:"Prioritaria",prog:"hd",as:"Inasistencia a hemodiálisis · {pid}",cu:"Se notifica que el paciente {pid} no asistió a la sesión de hemodiálisis programada ({det}). Se solicita búsqueda activa y valoración por trabajo social (red de apoyo, transporte, barreras de acceso) y registrar la gestión como respuesta a esta notificación."},
 {n:"Paciente sin sesión en 7 días → Trabajo social",para:"a:Trabajo social",tipo:"Notificación formal",pri:"Urgente",prog:"hd",as:"Paciente sin sesión de hemodiálisis · {pid}",cu:"El paciente {pid} completa {det} sin sesión de hemodiálisis realizada y sin hospitalización registrada. Riesgo clínico alto. Se solicita contacto inmediato y búsqueda activa; si no se localiza, informar a coordinación para activar la ruta de abandono."},
 {n:"Sospecha de bacteriemia → Laboratorio",para:"a:Laboratorio clínico",tipo:"Solicitud",pri:"Urgente",prog:"hd",as:"Hemocultivos pareados · {pid}",cu:"Paciente {pid} con sospecha de bacteriemia asociada a catéter. Se solicita procesamiento prioritario de hemocultivos pareados e informe del antibiograma para confirmar el caso en IAAS."},
 {n:"Antimicrobiano restringido → Química farmacéutica",para:"a:Servicio farmacéutico",tipo:"Solicitud",pri:"Prioritaria",prog:"proa",as:"Autorización de antimicrobiano restringido · {pid}",cu:"Se solicita revisión y autorización PROA del antimicrobiano restringido prescrito al paciente {pid}. Adjuntar justificación clínica y cultivo previo."},
 {n:"Libre",para:"",tipo:"Notificación formal",pri:"Rutina",prog:"",as:"",cu:""}];
const pxMine=m=>m.Para==="u:"+PX.user.ID||m.Para==="a:"+PX.user.Area;
const pxParaTxt=v=>!v?"":v.startsWith("a:")?"Área: "+v.slice(2):pxUN(v.slice(2));
function pxUnread(){if(!PX.user||!PX.book)return[];return PX.book.msg.filter(m=>pxMine(m)&&m.De!==PX.user.ID&&!m.LeidoEn);}
function pxVencidos(){if(!PX.book)return[];const t=pxToday();return PX.book.msg.filter(m=>m.Hilo===m.ID&&m.Plazo&&m.Plazo<t&&!["Respondido","Cerrado"].includes(m.Estado));}
function pxThreads(f){const roots=PX.book.msg.filter(m=>m.Hilo===m.ID);const me=PX.user.ID;
  return roots.filter(r=>{const th=PX.book.msg.filter(m=>m.Hilo===r.ID);if(f==="in")return th.some(m=>pxMine(m)&&m.De!==me);if(f==="out")return th.some(m=>m.De===me);if(f==="all")return pxAdmin()||PX.user.Area==="Calidad";return true;})
   .sort((a,b)=>pxLastTs(b).localeCompare(pxLastTs(a)));}
const pxLastTs=r=>PX.book.msg.filter(m=>m.Hilo===r.ID).map(m=>m.FechaHora).sort().pop()||r.FechaHora;
function pxMsgState(r){const t=pxToday();if(r.Estado==="Cerrado")return["Cerrado","base"];if(r.Estado==="Respondido")return["Respondido","ok"];if(r.Plazo&&r.Plazo<t)return["Plazo vencido","bad"];return[r.LeidoEn?"Leído":"Sin leer",r.LeidoEn?"warn":"bad"];}
function pxMsgList(L,compact){if(!L.length)return'<p class="note" style="padding:12px 14px;margin:0">Sin mensajes.</p>';
  return'<div class="tablebox"><table class="pxmt"><tbody>'+L.map(r=>{const[s,c]=pxMsgState(r);const un=PX.book.msg.some(m=>m.Hilo===r.ID&&pxMine(m)&&m.De!==PX.user.ID&&!m.LeidoEn);const n=PX.book.msg.filter(m=>m.Hilo===r.ID).length;
   return'<tr class="'+(un?"unread":"")+'"><td><button type="button" class="lnk pxsubj" data-p="th|'+r.ID+'">'+esc(r.Asunto)+'</button><span class="sub">'+esc(pxUN(r.De))+' → '+esc(pxParaTxt(r.Para))+(r.Paciente?' · paciente '+esc(r.Paciente):'')+(n>1?' · '+n+' mensajes':'')+'</span></td>'+(compact?'':'<td><span class="tag">'+esc(r.Tipo)+'</span>'+(r.Prioridad!=="Rutina"?' <span class="tag '+(r.Prioridad==="Urgente"?"bad":"warn")+'">'+esc(r.Prioridad)+'</span>':'')+'</td><td class="mono" style="font-size:12.5px">'+esc(pxLastTs(r))+(r.Plazo?'<span class="sub">plazo '+pxFD(r.Plazo)+'</span>':'')+'</td>')+'<td><span class="st '+c+'">'+s+'</span></td></tr>';}).join("")+'</tbody></table></div>';}
function pxMsg(){const f=PX.ui.sub||"in";const T=pxThreads(f);const th=PX.ui.th?PX.book.msg.find(m=>m.ID===PX.ui.th):null;
  let h='<div class="mhead"><div><h2 class="mt">Mensajes</h2><p class="note" style="margin:3px 0 0">Notificaciones formales entre usuarios y áreas. Cada mensaje queda con fecha y hora, acuse de lectura (quién y cuándo), plazo y respuesta. Sirve como soporte de gestión.</p></div><div class="copyrow"><button type="button" class="btn primary" data-p="compose">Nueva notificación</button><button type="button" class="btn" data-p="msgexp">Descargar trazabilidad</button></div></div>';
  h+='<div class="seg" role="group">'+[["in","Recibidos"],["out","Enviados"]].concat(pxAdmin()||PX.user.Area==="Calidad"?[["all","Todos (auditoría)"]]:[]).map(([k,l])=>'<button type="button" data-p="msub|'+k+'" aria-pressed="'+(f===k)+'">'+l+'</button>').join("")+'</div>';
  const tiles=[["Sin leer",pxUnread().length,"warn"],["Plazo vencido",pxVencidos().filter(r=>PX.book.msg.some(m=>m.Hilo===r.ID&&(pxMine(m)||m.De===PX.user.ID))).length,"bad"],["Respondidos (últimos 30 días)",PX.book.msg.filter(r=>r.Hilo===r.ID&&r.Estado==="Respondido"&&r.FechaHora>=iso(addDays(TODAY(),-30))&&PX.book.msg.some(m=>m.Hilo===r.ID&&(pxMine(m)||m.De===PX.user.ID))).length,"ok"]];
  h+='<div class="tiles">'+tiles.map(([l,v,c])=>'<div class="tile '+(v?c:"base")+'"><span class="tv">'+v+'</span><span class="tl">'+l+'</span></div>').join("")+'</div>';
  h+='<div class="pxmsg"><div class="panel" style="padding:0">'+pxMsgList(T)+'</div>'+(th?pxThread(th):'<div class="panel empty note">Elija un mensaje para leerlo y responder.</div>')+'</div>';return h;}
function pxThread(r){const L=PX.book.msg.filter(m=>m.Hilo===r.ID).sort((a,b)=>a.FechaHora.localeCompare(b.FechaHora));const[s,c]=pxMsgState(r);
  const canClose=r.Estado!=="Cerrado"&&(r.De===PX.user.ID||pxMine(r)||pxAdmin());
  return'<div class="panel pxth"><div class="mhead"><div><h3 style="margin:0">'+esc(r.Asunto)+'</h3><p class="note" style="margin:3px 0 0">'+esc(r.Tipo)+' · '+esc(r.Prioridad)+(r.Programa&&PROG[r.Programa]?' · '+esc(PROG[r.Programa].n):'')+(r.Paciente?' · paciente <span class="mono">'+esc(r.Paciente)+'</span>':'')+(r.Plazo?' · plazo '+pxFD(r.Plazo):'')+'</p></div><span class="st '+c+'">'+s+'</span></div>'+
  L.map(m=>'<article class="pxmm'+(m.De===PX.user.ID?" mine":"")+'"><header><b>'+esc(pxUN(m.De))+'</b> → '+esc(pxParaTxt(m.Para))+'<span class="mono">'+esc(m.FechaHora)+'</span></header><p>'+esc(m.Cuerpo).replace(/\n/g,"<br>")+'</p>'+(m.LeidoEn?'<footer>Leído por '+esc(pxUN(m.LeidoPor))+' el '+esc(m.LeidoEn)+'</footer>':(m.De!==PX.user.ID?'':'<footer>Aún sin acuse de lectura</footer>'))+'</article>').join("")+
  (r.Estado!=="Cerrado"?'<label class="f">Respuesta<textarea id="pxrep" rows="3" placeholder="Escriba la gestión realizada o la respuesta"></textarea></label><div class="copyrow"><button type="button" class="btn primary" data-p="reply|'+r.ID+'">Responder</button>'+(canClose?'<button type="button" class="btn" data-p="mclose|'+r.ID+'">Cerrar notificación</button>':'')+'</div>':'<p class="note">Cerrado el '+esc(r.CerradoEn)+'.</p>')+'</div>';}
function pxOpenThread(id){PX.ui.th=id;const t=pxNow();PX.book.msg.filter(m=>m.Hilo===id&&pxMine(m)&&m.De!==PX.user.ID&&!m.LeidoEn).forEach(m=>{m.LeidoEn=t;m.LeidoPor=PX.user.ID;pxLog("ACUSE","msg",m.ID,"");PX.dirty=true;});const r=PX.book.msg.find(m=>m.ID===id);if(r&&!r.LeidoEn&&pxMine(r)){r.LeidoEn=t;r.LeidoPor=PX.user.ID;}pxRender();}
function pxReply(id){const r=PX.book.msg.find(m=>m.ID===id);const tx=$("pxrep").value.trim();if(tx.length<3){toast("Escriba la respuesta.");return;}
  const to=r.De===PX.user.ID?r.Para:"u:"+r.De;pxAdd("msg","M-",{Hilo:id,FechaHora:pxNow(),De:PX.user.ID,Para:to,Tipo:"Respuesta",Prioridad:r.Prioridad,Asunto:"Re: "+r.Asunto,Cuerpo:tx,Paciente:r.Paciente,Programa:r.Programa,Plazo:"",Estado:""});
  if(r.De!==PX.user.ID)pxUpd("msg",r,{Estado:"Respondido"});pxRender();toast("Respuesta enviada.");}
function pxCompose(o){o=o||{};const H=pxHD();const pacs=(H?H.pac.map(p=>[p.ID,p.ID+" · "+nombre(p)]):[]).concat(typeof VX!=="undefined"&&VX.book?vxPacs().map(p=>[p.ID,p.ID+" · VIH"]):[]);
  const paraOpts='<optgroup label="Áreas">'+pxAreas().map(a=>'<option value="a:'+esc(a)+'"'+(o.para==="a:"+a?" selected":"")+'>'+esc(a)+'</option>').join("")+'</optgroup><optgroup label="Personas">'+PX.book.usr.filter(u=>u.Activo!=="NO"&&u.ID!==PX.user.ID).map(u=>'<option value="u:'+u.ID+'"'+(o.para==="u:"+u.ID?" selected":"")+'>'+esc(u.Nombre+" · "+u.Cargo)+'</option>').join("")+'</optgroup>';
  openDlg("Nueva notificación",'<div class="form"><label class="f wide">Plantilla<select id="mc_tpl">'+opt(MSG_TPL.map((t,i)=>[i,t.n]),o.tpl!=null?o.tpl:MSG_TPL.length-1)+'</select></label><label class="f wide">Para<select id="mc_to"><option value="">Elija área o persona…</option>'+paraOpts+'</select></label><label class="f">Tipo<select id="mc_ti">'+opt(MSG_TIPO,o.tipo||"Notificación formal")+'</select></label><label class="f">Prioridad<select id="mc_pr">'+opt(MSG_PRI,o.pri||"Rutina")+'</select></label><label class="f">Programa<select id="mc_pg">'+opt(PROGS.filter(p=>p.g!=="ges").map(p=>[p.k,p.n]),o.prog||"","—")+'</select></label><label class="f">Paciente (ID)<input type="text" id="mc_pid" list="mc_pl" value="'+esc(o.pid||"")+'"><datalist id="mc_pl">'+pacs.map(([v,l])=>'<option value="'+esc(v)+'">'+esc(l)+'</option>').join("")+'</datalist></label><label class="f">Plazo de respuesta<input type="date" id="mc_pz" value="'+(o.plazo||iso(addDays(TODAY(),2)))+'"></label><label class="f wide">Asunto<input type="text" id="mc_as" value="'+esc(o.as||"")+'"></label><label class="f wide">Mensaje<textarea id="mc_cu" rows="6">'+esc(o.cu||"")+'</textarea></label></div><p class="note">En el mensaje identifique al paciente solo con el ID de la herramienta; evite escribir diagnósticos que no sean necesarios para la gestión.</p>',"Enviar",()=>{
   const to=$("mc_to").value,as=$("mc_as").value.trim(),cu=$("mc_cu").value.trim();if(!to)return"Elija el destinatario.";if(as.length<4||cu.length<10)return"Escriba asunto y mensaje.";
   const r=pxAdd("msg","M-",{Hilo:"",FechaHora:pxNow(),De:PX.user.ID,Para:to,Tipo:$("mc_ti").value,Prioridad:$("mc_pr").value,Asunto:as,Cuerpo:cu,Paciente:$("mc_pid").value.trim(),Programa:$("mc_pg").value,Plazo:$("mc_pz").value,Estado:"Enviado"});r.Hilo=r.ID;
   pxBar();if(!document.getElementById("pxmain").hidden)pxRender();toast("Notificación enviada a "+pxParaTxt(to)+".");});
  $("mc_tpl").onchange=e=>{const t=MSG_TPL[+e.target.value];const pid=$("mc_pid").value.trim()||o.pid||"";const det=o.det||"";const f=s=>s.replace(/\{pid\}/g,pid||"[ID]").replace(/\{det\}/g,det||"[detalle]");if(t.para)$("mc_to").value=t.para;$("mc_ti").value=t.tipo;$("mc_pr").value=t.pri;$("mc_pg").value=t.prog;$("mc_as").value=f(t.as);$("mc_cu").value=f(t.cu);};
  if(o.tpl!=null)$("mc_tpl").onchange({target:$("mc_tpl")});}
function pxMsgExp(){const L=(pxAdmin()||PX.user.Area==="Calidad"?PX.book.msg:PX.book.msg.filter(m=>m.De===PX.user.ID||pxMine(m)));
  pxExport("Trazabilidad_mensajes_"+pxToday()+".xlsx",[["Mensajes",L,[["ID",m=>m.ID],["Hilo",m=>m.Hilo],["Fecha y hora",m=>m.FechaHora],["De",m=>pxUN(m.De)],["Para",m=>pxParaTxt(m.Para)],["Tipo",m=>m.Tipo],["Prioridad",m=>m.Prioridad],["Programa",m=>PROG[m.Programa]?PROG[m.Programa].n:""],["Paciente",m=>m.Paciente],["Asunto",m=>m.Asunto],["Mensaje",m=>m.Cuerpo],["Plazo",m=>m.Plazo],["Estado",m=>m.Estado],["Leído en",m=>m.LeidoEn],["Leído por",m=>m.LeidoPor?pxUN(m.LeidoPor):""],["Cerrado en",m=>m.CerradoEn]]]]);}

/* ---------- documentos y guías ---------- */
const DOC_TIPO=["Programa","Protocolo","Guía","Procedimiento","Manual","Instructivo","Formato","Matriz","Política","Plan","Guía de práctica clínica externa","Norma"];
const DOC_EST=["Vigente","Por confirmar","En revisión","En elaboración","Obsoleto"];
const pxDocEdit=()=>pxAdmin()||PX.user.Area==="Calidad";
function pxDocsTable(L,title){const t=pxToday();
  return'<div class="panel"><h3>'+esc(title)+' ('+L.length+')</h3>'+(L.length?'<div class="tablebox"><table><thead><tr><th>Código</th><th>Documento</th><th>Tipo</th><th>Versión</th><th>Próxima revisión</th><th>Estado</th><th>Abrir</th>'+(pxDocEdit()?'<th></th>':'')+'</tr></thead><tbody>'+L.map(d=>{const venc=d.ProximaRevision&&d.ProximaRevision<t&&d.Estado==="Vigente";
   return'<tr><td class="mono">'+esc(d.Codigo||"—")+'</td><td><strong>'+esc(d.Nombre)+'</strong><span class="sub">'+esc(String(d.Programas).split(",").filter(Boolean).map(k=>PROG[k]?PROG[k].n:k).join(" · ")||"Institucional")+(d.Responsable?' · '+esc(d.Responsable):'')+'</span></td><td>'+esc(d.Tipo)+'</td><td class="mono">'+esc(d.Version||"por confirmar")+(d.FechaAprobacion?'<span class="sub">'+pxFD(d.FechaAprobacion)+'</span>':'')+'</td><td class="mono'+(venc?" bad-t":"")+'">'+(d.ProximaRevision?pxFD(d.ProximaRevision)+(venc?'<span class="sub">vencida</span>':''):'—')+'</td><td><span class="st '+(d.Estado==="Vigente"?"ok":d.Estado==="Obsoleto"?"base":"warn")+'">'+esc(d.Estado)+'</span></td><td>'+pxDocLink(d)+'</td>'+(pxDocEdit()?'<td><button type="button" class="btn sm" data-p="docedit|'+d.ID+'">Editar</button></td>':'')+'</tr>';}).join("")+'</tbody></table></div>':'<p class="note">Sin documentos asociados.</p>')+'</div>';}
function pxDocLink(d){const e=String(d.Enlace||"").trim();if(!e)return'<span class="sd">sin enlace</span>';if(/^https?:\/\//i.test(e))return'<a class="lnk" href="'+esc(e)+'" target="_blank" rel="noopener">Abrir</a>';return'<button type="button" class="lnk" data-p="copy|'+esc(e)+'" title="'+esc(e)+'">Copiar ruta</button>';}
function pxDocs(){if(PX.ui.sub==="ruta")return pxDocsHead()+pxRutaView(false);const f=PX.ui.df||{};const q=(f.q||"").toLowerCase();const L=PX.book.doc.filter(d=>(!f.p||String(d.Programas).split(",").includes(f.p))&&(!f.t||d.Tipo===f.t)&&(!f.e||d.Estado===f.e)&&(!q||(d.Codigo+" "+d.Nombre).toLowerCase().includes(q)));
  const int=L.filter(d=>d.Fuente!=="Externo"),ext=L.filter(d=>d.Fuente==="Externo");
  return pxDocsHead()+
  '<div class="filters panel"><label class="f">Buscar<input type="text" id="pxdq" value="'+esc(f.q||"")+'" placeholder="código o nombre"></label><label class="f">Programa<select id="pxdp">'+opt(PROGS.filter(p=>p.g!=="ges").map(p=>[p.k,p.n]),f.p||"","Todos")+'</select></label><label class="f">Tipo<select id="pxdt">'+opt(DOC_TIPO,f.t||"","Todos")+'</select></label><label class="f">Estado<select id="pxde">'+opt(DOC_EST,f.e||"","Todos")+'</select></label></div>'+
  pxDocsTable(int,"Documentos institucionales")+pxDocsTable(ext,"Guías de práctica clínica y referentes externos")+'<p class="note">Los enlaces externos precargados apuntan a la página general de cada organismo; verifique la versión vigente antes de usarlos como soporte.</p>';}
function pxDocsHead(){const sub=PX.ui.sub==="ruta"?"ruta":"lm";return'<div class="mhead"><div><h2 class="mt">Documentos y guías</h2><p class="note" style="margin:3px 0 0">Listado maestro de documentos del sistema de gestión de calidad, direccionamiento a guías de práctica clínica y ruta del paciente. Los enlaces web se abren en una pestaña nueva; las rutas de la carpeta de red se copian para pegarlas en el explorador de archivos.</p></div>'+(pxDocEdit()&&sub==="lm"?'<div class="copyrow"><button type="button" class="btn primary" data-p="docedit|">Agregar documento</button><button type="button" class="btn" data-p="docexp">Descargar listado maestro</button></div>':'')+'</div><div class="seg" role="group">'+[["lm","Listado maestro"],["ruta","Ruta del paciente en hemodiálisis"]].map(([k,l])=>'<button type="button" data-p="go|docs|'+(k==="lm"?"":k)+'" aria-pressed="'+(sub===k)+'">'+l+'</button>').join("")+'</div>';}
function pxDocsFor(k){if(!PX.book)return'<div class="panel empty">Abra el sistema desde la portada para ver los documentos.</div>';const L=PX.book.doc.filter(d=>String(d.Programas).split(",").includes(k));
  return head("Documentos y guías","Documentos de calidad, guías de práctica clínica del programa y ruta del paciente. El listado maestro completo está en Documentos y guías del panel.")+(k==="hd"?pxRutaView(false):"")+pxDocsTable(L.filter(d=>d.Fuente!=="Externo"),"Documentos de calidad del servicio")+pxDocsTable(L.filter(d=>d.Fuente==="Externo"),"Guías de práctica clínica (direccionamiento)");}
function pxDlgDoc(id){const d=id?PX.book.doc.find(x=>x.ID===id):null;const pr=d?String(d.Programas).split(","):[];
  openDlg(d?"Editar documento":"Agregar documento",'<div class="form"><label class="f">Código<input type="text" id="dc_c" value="'+esc(d?d.Codigo:"")+'"></label><label class="f wide">Nombre<input type="text" id="dc_n" value="'+esc(d?d.Nombre:"")+'"></label><label class="f">Tipo<select id="dc_t">'+opt(DOC_TIPO,d?d.Tipo:"Protocolo")+'</select></label><label class="f">Origen<select id="dc_o">'+opt([["Interno","Institucional"],["Externo","Externo (guía, norma)"]],d?d.Fuente:"Interno")+'</select></label><label class="f">Versión<input type="text" id="dc_v" value="'+esc(d?d.Version:"")+'"></label><label class="f">Fecha de aprobación<input type="date" id="dc_fa" value="'+esc(d?d.FechaAprobacion:"")+'"></label><label class="f">Próxima revisión<input type="date" id="dc_pr" value="'+esc(d?d.ProximaRevision:"")+'"></label><label class="f">Estado<select id="dc_e">'+opt(DOC_EST,d?d.Estado:"Vigente")+'</select></label><label class="f">Responsable<input type="text" id="dc_r" value="'+esc(d?d.Responsable:"")+'"></label><label class="f wide">Enlace (URL de Drive/SharePoint o ruta de red)<input type="text" id="dc_l" value="'+esc(d?d.Enlace:"")+'" placeholder="https://… o \\\\servidor\\calidad\\…"></label></div><fieldset class="pxfs"><legend>Programas</legend><div class="cols2">'+PROGS.filter(p=>p.g!=="ges").map(p=>'<label class="chk"><input type="checkbox" data-dprog="'+p.k+'"'+(pr.includes(p.k)?" checked":"")+'> '+esc(p.n)+'</label>').join("")+'</div></fieldset>',"Guardar",()=>{
   const o={Codigo:$("dc_c").value.trim(),Nombre:$("dc_n").value.trim(),Tipo:$("dc_t").value,Fuente:$("dc_o").value,Version:$("dc_v").value.trim(),FechaAprobacion:$("dc_fa").value,ProximaRevision:$("dc_pr").value,Estado:$("dc_e").value,Responsable:$("dc_r").value.trim(),Enlace:$("dc_l").value.trim(),Programas:[...document.querySelectorAll("[data-dprog]:checked")].map(x=>x.dataset.dprog).join(",")};
   if(o.Nombre.length<4)return"Escriba el nombre del documento.";if(d)pxUpd("doc",d,o);else pxAdd("doc","D-",o);pxRefresh();toast("Documento guardado.");});}
function pxDocExp(){pxExport("Listado_maestro_documentos_"+pxToday()+".xlsx",[["Listado maestro",PX.book.doc,[["Código",d=>d.Codigo],["Nombre",d=>d.Nombre],["Tipo",d=>d.Tipo],["Origen",d=>d.Fuente],["Programas",d=>String(d.Programas).split(",").filter(Boolean).map(k=>PROG[k]?PROG[k].n:k).join(", ")],["Versión",d=>d.Version],["Aprobación",d=>d.FechaAprobacion],["Próxima revisión",d=>d.ProximaRevision],["Estado",d=>d.Estado],["Responsable",d=>d.Responsable],["Enlace",d=>d.Enlace]]]]);}

/* ---------- SOGCS: comités ---------- */
const FREQ={Mensual:1,Bimestral:2,Trimestral:3,Cuatrimestral:4,Semestral:6,Anual:12};
function pxComPeriods(c,y){const st=FREQ[c.Frecuencia]||1;const mi=+c.MesInicio||1;const L=[];for(let m=1;m<=12;m++){if(((m-mi)%st+st)%st===0)L.push(y+"-"+String(m).padStart(2,"0"));}return L;}
const pxComSes=(cid,per)=>PX.book.cse.find(s=>s.Comite===cid&&s.Periodo===per&&s.Estado!=="Anulado");
function pxComCump(y,upto){let p=0,r=0;PX.book.com.filter(c=>c.Activo!=="NO").forEach(c=>pxComPeriods(c,y).forEach(per=>{if(per>=upto)return;p++;const s=pxComSes(c.ID,per);if(s&&s.Estado==="Realizado")r++;}));return{p,r};}
function pxCmpEst(x){if(x.Estado==="Cerrado")return"Cerrado";return x.FechaLimite&&x.FechaLimite<pxToday()?"Vencido":"Abierto";}
const pxRespTxt=v=>!v?"":pxU(v)?pxUN(v):v;
function pxSogcs(){const sub=PX.ui.sub||"cal";
  let h='<div class="mhead"><div><p class="eyebrow">Sistema Obligatorio de Garantía de Calidad en Salud</p><h2 class="mt">SOGCS · Comités institucionales</h2><p class="note" style="margin:3px 0 0">Cada comité se programa según su frecuencia. Una sesión cuenta como realizada con fecha, acta y quórum; los compromisos se siguen hasta su cierre.</p></div><div class="copyrow"><button type="button" class="btn" data-p="sogexp">Descargar seguimiento</button></div></div>';
  h+='<div class="seg" role="group">'+[["cal","Calendario y cumplimiento"],["cmp","Compromisos"],["cat","Catálogo de comités"]].map(([k,l])=>'<button type="button" data-p="go|sogcs|'+k+'" aria-pressed="'+(sub===k)+'">'+l+'</button>').join("")+'</div>';
  return h+({cal:pxSogCal,cmp:pxSogCmp,cat:pxSogCat})[sub]();}
function pxSogCal(){const y=PX.ui.year||pxMes().slice(0,4);const cur=ym(TODAY());const C=PX.book.com.filter(c=>c.Activo!=="NO");const tot=pxComCump(y,cur);
  const cmpO=PX.book.cmp.filter(x=>pxCmpEst(x)!=="Cerrado"),cmpV=PX.book.cmp.filter(x=>pxCmpEst(x)==="Vencido");
  let h='<div class="tiles"><div class="tile '+(tot.p?(tot.r/tot.p>=0.9?"ok":tot.r/tot.p>=0.7?"warn":"bad"):"base")+'"><span class="tv">'+(tot.p?Math.round(tot.r/tot.p*100)+" %":"—")+'</span><span class="tl">sesiones realizadas / programadas en meses cerrados ('+tot.r+' de '+tot.p+')</span></div><div class="tile warn"><span class="tv">'+cmpO.length+'</span><span class="tl">compromisos abiertos</span></div><div class="tile '+(cmpV.length?"bad":"ok")+'"><span class="tv">'+cmpV.length+'</span><span class="tl">compromisos vencidos</span></div></div>';
  h+='<div class="panel tablebox" style="padding:0"><div class="copyrow" style="padding:12px 12px 0"><label class="f" style="max-width:120px">Año<select id="pxyear">'+opt([String(+y-1),y,String(+y+1)],y)+'</select></label><span class="note">✓ realizado · ● pendiente (mes pasado sin sesión) · ○ programado · Haga clic en una celda para registrar o ver la sesión.</span></div><table class="pxcal"><thead><tr><th>Comité</th><th>Frecuencia</th>'+PMESES.map(m=>'<th class="num">'+m.slice(0,3)+'</th>').join("")+'<th class="num">Cumpl.</th></tr></thead><tbody>'+
  C.map(c=>{const P=pxComPeriods(c,y);let pp=0,rr=0;const cells=PMESES.map((_,i)=>{const per=y+"-"+String(i+1).padStart(2,"0");if(!P.includes(per))return'<td class="num sd">·</td>';const s=pxComSes(c.ID,per);let cl,tx;
     if(s&&s.Estado==="Realizado"){cl="ok";tx="✓";}else if(s&&s.Estado==="Cancelado"){cl="bad";tx="✕";}else if(per<cur){cl="bad";tx="●";}else{cl="base";tx="○";}if(per<cur){pp++;if(s&&s.Estado==="Realizado")rr++;}
     return'<td class="num"><button type="button" class="pxcc '+cl+'" data-p="cses|'+c.ID+'|'+per+'" title="'+esc(c.Nombre+" · "+per+(s?" · "+s.Estado:""))+'">'+tx+'</button></td>';}).join("");
   return'<tr><td><strong>'+esc(c.Nombre)+'</strong><span class="sub">'+esc(c.Norma||"")+'</span></td><td>'+esc(c.Frecuencia)+'</td>'+cells+'<td class="num mono">'+(pp?Math.round(rr/pp*100)+" %":"—")+'</td></tr>';}).join("")+'</tbody></table></div>';
  return h+'<p class="note">Frecuencias y normas precargadas para la demostración. Confírmelas contra el acto administrativo de creación de cada comité en la institución antes de usar el indicador.</p>';}
function pxDlgSes(cid,per){const c=PX.book.com.find(x=>x.ID===cid);const s=pxComSes(cid,per);const cm=s?PX.book.cmp.filter(x=>x.Sesion===s.ID):[];
  const resp=opt([["","—"]].concat(PX.book.usr.filter(u=>u.Activo!=="NO").map(u=>[u.ID,u.Nombre+" · "+u.Cargo])).concat(pxAreas().map(a=>[a,"Área: "+a])),"");
  openDlg(c.Nombre+" · "+pxMesTxt(per),(s?'<p class="note">Registrada por '+esc(s.Usuario)+'. Al guardar se actualiza la misma sesión.</p>':'')+'<div class="form"><label class="f">Estado<select id="cs_e">'+opt(["Realizado","Cancelado","Reprogramado"],s?s.Estado:"Realizado")+'</select></label><label class="f">Fecha<input type="date" id="cs_f" value="'+esc(s?s.Fecha:((PX.book.cal.find(x=>x.Comite===cid&&String(x.Fecha).startsWith(per)&&x.Estado!=="Cancelada")||{}).Fecha||""))+'"></label><label class="f">Acta (código o número)<input type="text" id="cs_a" value="'+esc(s?s.Acta:"")+'"></label><label class="f">Asistentes<input type="number" id="cs_n" value="'+esc(s?s.Asistentes:"")+'"></label><label class="f">¿Quórum?<select id="cs_q">'+opt(["Sí","No"],s?s.Quorum:"Sí")+'</select></label><label class="f wide">Enlace al acta<input type="text" id="cs_l" value="'+esc(s?s.Enlace:"")+'"></label><label class="f wide">Temas o nota<textarea id="cs_t" rows="2">'+esc(s?s.Nota:"")+'</textarea></label></div>'+
   (cm.length?'<div class="note"><strong>Compromisos de esta sesión:</strong> '+cm.map(x=>esc(x.Descripcion)+' ('+pxCmpEst(x)+')').join(" · ")+'</div>':'')+
   '<fieldset class="pxfs"><legend>Nuevos compromisos (opcional)</legend>'+[1,2,3].map(i=>'<div class="pxcmprow"><input type="text" id="cc_d'+i+'" placeholder="Compromiso"><select id="cc_r'+i+'">'+resp+'</select><input type="date" id="cc_f'+i+'"></div>').join("")+'</fieldset>',"Guardar",()=>{
   const e=$("cs_e").value,f=$("cs_f").value;if(e==="Realizado"&&(!f||!$("cs_a").value.trim()))return"Para marcar como realizado registre la fecha y el acta.";if(f&&f>pxToday())return"La fecha no puede ser futura.";
   const o={Comite:cid,Periodo:per,Fecha:f,Acta:$("cs_a").value.trim(),Enlace:$("cs_l").value.trim(),Asistentes:$("cs_n").value,Quorum:$("cs_q").value,Estado:e,Nota:$("cs_t").value.trim()};
   let r=s;if(r)pxUpd("cse",r,o);else r=pxAdd("cse","CS-",o);
   [1,2,3].forEach(i=>{const d=$("cc_d"+i).value.trim();if(!d)return;pxAdd("cmp","CP-",{Comite:cid,Sesion:r.ID,Descripcion:d,Responsable:$("cc_r"+i).value,FechaLimite:$("cc_f"+i).value,Estado:"Abierto"});});
   pxRender();toast("Sesión de "+c.Nombre+" guardada.");});}
function pxSogCmp(){const f=PX.ui.cf||"abiertos";const L=PX.book.cmp.filter(x=>f==="todos"||(f==="abiertos"?pxCmpEst(x)!=="Cerrado":pxCmpEst(x)==="Vencido")).sort((a,b)=>String(a.FechaLimite).localeCompare(String(b.FechaLimite)));
  return'<div class="seg" role="group">'+[["abiertos","Abiertos"],["vencidos","Vencidos"],["todos","Todos"]].map(([k,l])=>'<button type="button" data-p="cf|'+k+'" aria-pressed="'+(f===k)+'">'+l+'</button>').join("")+'</div><div class="panel tablebox" style="padding:0"><table><thead><tr><th>Comité</th><th>Compromiso</th><th>Responsable</th><th>Fecha límite</th><th>Estado</th><th></th></tr></thead><tbody>'+
  (L.map(x=>{const c=PX.book.com.find(k=>k.ID===x.Comite);const e=pxCmpEst(x);return'<tr><td>'+esc(c?c.Nombre:x.Comite)+'</td><td>'+esc(x.Descripcion)+(x.Evidencia?'<span class="sub">Evidencia: '+esc(x.Evidencia)+'</span>':'')+'</td><td>'+esc(pxRespTxt(x.Responsable))+'</td><td class="mono">'+pxFD(x.FechaLimite)+'</td><td><span class="st '+(e==="Cerrado"?"ok":e==="Vencido"?"bad":"warn")+'">'+e+'</span></td><td>'+(e!=="Cerrado"?'<button type="button" class="btn sm" data-p="cmpclose|'+x.ID+'">Cerrar</button>':'')+'</td></tr>';}).join("")||'<tr><td colspan="6" class="note">Sin compromisos.</td></tr>')+'</tbody></table></div>';}
function pxSogCat(){return'<div class="panel tablebox" style="padding:0"><table><thead><tr><th>Comité</th><th>Frecuencia</th><th>Mes de inicio</th><th>Norma o soporte</th><th>Secretaría técnica</th><th>Estado</th><th></th></tr></thead><tbody>'+PX.book.com.map(c=>'<tr><td><strong>'+esc(c.Nombre)+'</strong><span class="sub">'+esc(c.Integrantes||"")+'</span></td><td>'+esc(c.Frecuencia)+'</td><td>'+esc(PMESES[(+c.MesInicio||1)-1])+'</td><td style="font-size:13px">'+esc(c.Norma)+'</td><td>'+esc(pxRespTxt(c.Responsable))+'</td><td>'+(c.Activo==="NO"?'<span class="st base">Inactivo</span>':'<span class="st ok">Activo</span>')+'</td><td>'+(pxDocEdit()?'<button type="button" class="btn sm" data-p="comedit|'+c.ID+'">Editar</button>':'')+'</td></tr>').join("")+'</tbody></table></div>'+(pxDocEdit()?'<button type="button" class="btn" data-p="comedit|">Agregar comité</button>':'');}
function pxDlgCom(id){const c=id?PX.book.com.find(x=>x.ID===id):null;
  openDlg(c?"Editar comité":"Agregar comité",'<div class="form"><label class="f wide">Nombre<input type="text" id="cm_n" value="'+esc(c?c.Nombre:"")+'"></label><label class="f">Frecuencia<select id="cm_f">'+opt(Object.keys(FREQ),c?c.Frecuencia:"Mensual")+'</select></label><label class="f">Mes de inicio<select id="cm_m">'+opt(PMESES.map((m,i)=>[i+1,m]),c?c.MesInicio:1)+'</select></label><label class="f wide">Norma o soporte<input type="text" id="cm_no" value="'+esc(c?c.Norma:"")+'"></label><label class="f">Secretaría técnica<select id="cm_r">'+opt(PX.book.usr.map(u=>[u.ID,u.Nombre]),c?c.Responsable:"","—")+'</select></label><label class="f">Estado<select id="cm_e">'+opt([["SI","Activo"],["NO","Inactivo"]],c?c.Activo:"SI")+'</select></label><label class="f wide">Integrantes<input type="text" id="cm_i" value="'+esc(c?c.Integrantes:"")+'"></label></div>',"Guardar",()=>{
   const o={Nombre:$("cm_n").value.trim(),Frecuencia:$("cm_f").value,MesInicio:$("cm_m").value,Norma:$("cm_no").value.trim(),Responsable:$("cm_r").value,Activo:$("cm_e").value,Integrantes:$("cm_i").value.trim()};if(o.Nombre.length<4)return"Escriba el nombre.";if(c)pxUpd("com",c,o);else pxAdd("com","CO-",o);pxRender();toast("Comité guardado.");});}
function pxSogExp(){const y=PX.ui.year||pxMes().slice(0,4);const rows=[];PX.book.com.forEach(c=>pxComPeriods(c,y).forEach(per=>{const s=pxComSes(c.ID,per);rows.push({c,per,s});}));
  pxExport("SOGCS_comites_"+y+".xlsx",[["Programación",rows,[["Comité",r=>r.c.Nombre],["Frecuencia",r=>r.c.Frecuencia],["Periodo",r=>r.per],["Estado",r=>r.s?r.s.Estado:(r.per<ym(TODAY())?"Pendiente (no realizado)":"Programado")],["Fecha",r=>r.s?r.s.Fecha:""],["Acta",r=>r.s?r.s.Acta:""],["Quórum",r=>r.s?r.s.Quorum:""],["Asistentes",r=>r.s?r.s.Asistentes:""],["Enlace",r=>r.s?r.s.Enlace:""]]],["Compromisos",PX.book.cmp,[["Comité",x=>(PX.book.com.find(c=>c.ID===x.Comite)||{}).Nombre],["Compromiso",x=>x.Descripcion],["Responsable",x=>pxRespTxt(x.Responsable)],["Fecha límite",x=>x.FechaLimite],["Estado",x=>pxCmpEst(x)],["Cierre",x=>x.FechaCierre],["Evidencia",x=>x.Evidencia]]]]);}

