/* ================= calendario de actividades ================= */
const CAL_TIPOS=[["Reunión","c1"],["Capacitación","c2"],["Comité","c3"],["Jornada o brigada","c4"],["Auditoría o visita","c5"],["Actividad institucional","c6"]];
const CAL_CLS=Object.fromEntries(CAL_TIPOS);
const CAL_MOD=["Presencial","Virtual","Mixta"];
const CAL_DIAS=["Lun","Mar","Mié","Jue","Vie","Sáb","Dom"];
const pxCalInv=e=>String(e.Invitados||"").split(",").map(s=>s.trim()).filter(Boolean);
function pxCalResp(e){try{return JSON.parse(e.Respuestas||"{}");}catch(x){return{};}}
function pxCalMine(e){const me=PX.user;return e.Responsable===me.ID||e.Creador===me.ID||pxCalInv(e).some(i=>i==="u:"+me.ID||i==="a:"+me.Area);}
function pxCalInvited(e){const me=PX.user;return e.Responsable!==me.ID&&pxCalInv(e).some(i=>i==="u:"+me.ID||i==="a:"+me.Area);}
function pxCalCanEdit(e){return pxAdmin()||e.Responsable===PX.user.ID||e.Creador===PX.user.ID;}
function pxCalVisible(e){return e.Visibilidad!=="Solo invitados"||pxCalMine(e)||pxAdmin();}
const pxCalHora=e=>(e.HoraInicio||"")+(e.HoraFin?"–"+e.HoraFin:"");
/* actividades propias + derivadas de SOGCS (sesiones con fecha y vencimiento de compromisos) */
function pxCalItems(a,b){const L=PX.book.cal.filter(e=>e.Fecha>=a&&e.Fecha<=b&&pxCalVisible(e)).map(e=>Object.assign({src:"cal"},e));
  const lk=new Set(PX.book.cal.filter(e=>e.Comite).map(e=>e.Comite+"|"+e.Fecha));
  PX.book.cse.filter(s=>s.Fecha&&s.Fecha>=a&&s.Fecha<=b&&s.Estado==="Realizado"&&!lk.has(s.Comite+"|"+s.Fecha)).forEach(s=>{const c=PX.book.com.find(x=>x.ID===s.Comite);L.push({src:"cse",ID:s.ID,Titulo:c?c.Nombre:"Comité",Tipo:"Comité",Fecha:s.Fecha,HoraInicio:"",Estado:"Realizada",Nota:"Acta "+s.Acta,Comite:s.Comite});});
  PX.book.cmp.filter(x=>x.FechaLimite&&x.FechaLimite>=a&&x.FechaLimite<=b&&x.Estado!=="Cerrado").forEach(x=>{const c=PX.book.com.find(k=>k.ID===x.Comite);L.push({src:"cmp",ID:x.ID,Titulo:"Vence: "+x.Descripcion,Tipo:"Vencimiento",Fecha:x.FechaLimite,HoraInicio:"",Estado:pxCmpEst(x),Nota:c?c.Nombre:""});});
  const f=PX.ui.calt||"";const solo=PX.ui.calm;return L.filter(e=>(!f||e.Tipo===f)&&(!solo||e.src!=="cal"||pxCalMine(e))).sort((x,y)=>(x.Fecha+(x.HoraInicio||"99")).localeCompare(y.Fecha+(y.HoraInicio||"99")));}
function pxCalChip(e,short){const cls=e.src==="cmp"?"cv":CAL_CLS[e.Tipo]||"c6";const st=e.Estado==="Cancelada"?" cancel":"";
  return'<button type="button" class="calchip '+cls+st+'" data-p="cev|'+e.src+'|'+e.ID+'" title="'+esc((e.HoraInicio?e.HoraInicio+" · ":"")+e.Titulo)+'">'+(e.HoraInicio&&!short?'<span class="mono">'+esc(e.HoraInicio)+'</span> ':'')+esc(e.Titulo)+'</button>';}
function pxCal(){if(PX.ui.sub){PX.ui.calv=PX.ui.sub;PX.ui.sub=null;}const v=PX.ui.calv||"mes";const base=pdate((PX.ui.calm0||ym(TODAY()))+"-01");const ms=iso(monthStart(base)),me=iso(monthEnd(base));const hoy=pxToday();
  const mt=PMESES[base.getMonth()]+" de "+base.getFullYear();
  let h='<div class="mhead"><div><h2 class="mt">Calendario de actividades</h2><p class="note" style="margin:3px 0 0">Reuniones, capacitaciones, comités, jornadas y visitas de la clínica. Todos ven las actividades generales; las marcadas «solo invitados» las ven el responsable y sus invitados. Los comités realizados y los vencimientos de compromisos del SOGCS aparecen solos.</p></div><div class="copyrow"><button type="button" class="btn primary" data-p="calnew|'+(PX.ui.cald||"")+'">Nueva actividad</button><button type="button" class="btn" data-p="calexp">Descargar mes</button></div></div>';
  h+='<div class="calbar"><div class="copyrow"><button type="button" class="btn sm" data-p="calnav|-1" aria-label="Mes anterior">‹</button><strong class="calmt">'+mt+'</strong><button type="button" class="btn sm" data-p="calnav|1" aria-label="Mes siguiente">›</button><button type="button" class="btn sm" data-p="calnav|0">Hoy</button></div>'+
   '<div class="seg" role="group">'+[["mes","Mes"],["agenda","Agenda"]].map(([k,l])=>'<button type="button" data-p="calv|'+k+'" aria-pressed="'+(v===k)+'">'+l+'</button>').join("")+'</div>'+
   '<label class="f" style="max-width:200px">Tipo<select id="pxcalt">'+opt(CAL_TIPOS.map(t=>t[0]).concat(["Vencimiento"]),PX.ui.calt||"","Todos")+'</select></label><label class="chk" style="font-size:13.5px"><input type="checkbox" id="pxcalm"'+(PX.ui.calm?" checked":"")+'> Solo donde participo</label></div>';
  const mineSoon=PX.book.cal.filter(e=>e.Fecha>=hoy&&e.Fecha<=iso(addDays(TODAY(),7))&&e.Estado!=="Cancelada"&&pxCalMine(e));const pend=mineSoon.filter(e=>pxCalInvited(e)&&!pxCalResp(e)[PX.user.ID]);
  h+='<div class="tiles"><div class="tile"><span class="tv">'+PX.book.cal.filter(e=>e.Fecha===hoy&&e.Estado!=="Cancelada"&&pxCalVisible(e)).length+'</span><span class="tl">actividades hoy</span></div><div class="tile"><span class="tv">'+mineSoon.length+'</span><span class="tl">en las que participa (próximos 7 días)</span></div><div class="tile '+(pend.length?"warn":"ok")+'"><span class="tv">'+pend.length+'</span><span class="tl">invitaciones sin confirmar</span></div></div>';
  const I=pxCalItems(ms,me);
  if(v==="agenda"){const g={};I.forEach(e=>(g[e.Fecha]=g[e.Fecha]||[]).push(e));
    h+='<div class="panel calag">'+(Object.keys(g).length?Object.entries(g).map(([d,L])=>{const dd=pdate(d);return'<section class="'+(d===hoy?"today":"")+'"><h4><span class="mono">'+fd(dd).slice(0,5)+'</span> '+CAL_DIAS[(dd.getDay()+6)%7]+(d===hoy?' · hoy':'')+'</h4>'+L.map(e=>pxCalRow(e)).join("")+'</section>';}).join(""):'<p class="note">Sin actividades en '+esc(mt.toLowerCase())+'.</p>')+'</div>';}
  else{const first=monthStart(base);const off=(first.getDay()+6)%7;const start=addDays(first,-off);const days=[];for(let i=0;i<42;i++){const d=addDays(start,i);if(i>=35&&d.getMonth()!==base.getMonth())break;days.push(d);}
    const sel=PX.ui.cald||"";
    h+='<div class="panel calm" style="padding:0"><div class="calgrid calhead">'+CAL_DIAS.map(d=>'<div>'+d+'</div>').join("")+'</div><div class="calgrid">'+days.map(d=>{const k=iso(d);const L=I.filter(e=>e.Fecha===k);const out=d.getMonth()!==base.getMonth();
      return'<div class="calday'+(out?" out":"")+(k===hoy?" today":"")+(k===sel?" sel":"")+'"><button type="button" class="calnum" data-p="cald|'+k+'" aria-label="Ver '+fd(d)+'">'+d.getDate()+'</button>'+L.slice(0,3).map(e=>pxCalChip(e)).join("")+(L.length>3?'<button type="button" class="lnk calmore" data-p="cald|'+k+'">+'+(L.length-3)+' más</button>':'')+'</div>';}).join("")+'</div></div>';
    const sd=sel&&sel>=ms&&sel<=me?sel:(hoy>=ms&&hoy<=me?hoy:"");if(sd){const L=I.filter(e=>e.Fecha===sd);h+='<div class="panel"><div class="mhead"><h3 style="margin:0">'+esc(fd(pdate(sd)))+' · '+CAL_DIAS[(pdate(sd).getDay()+6)%7]+'</h3><button type="button" class="btn sm" data-p="calnew|'+sd+'">Agregar en este día</button></div>'+(L.length?L.map(e=>pxCalRow(e)).join(""):'<p class="note">Sin actividades este día.</p>')+'</div>';}
    const sinF=PX.book.com.filter(c=>c.Activo!=="NO"&&pxComPeriods(c,String(base.getFullYear())).includes(ym(base))&&!pxComSes(c.ID,ym(base))&&!PX.book.cal.some(e=>e.Comite===c.ID&&e.Fecha>=ms&&e.Fecha<=me));
    if(sinF.length)h+='<div class="panel"><h3>Comités programados este mes sin fecha en el calendario</h3><div class="copyrow">'+sinF.map(c=>'<button type="button" class="btn sm" data-p="calcom|'+c.ID+'">'+esc(c.Nombre)+'</button>').join("")+'</div><p class="note">Toque un comité para asignarle fecha, hora e invitados.</p></div>';}
  h+='<div class="calleg">'+CAL_TIPOS.map(([t,c])=>'<span><i class="'+c+'"></i>'+esc(t)+'</span>').join("")+'<span><i class="cv"></i>Vencimiento de compromiso</span></div>';
  return h;}
function pxCalRow(e){const cls=e.src==="cmp"?"cv":CAL_CLS[e.Tipo]||"c6";let extra="";
  if(e.src==="cal"){const R=pxCalResp(e);const inv=pxCalInv(e);const si=Object.values(R).filter(x=>x==="Sí").length;extra='<span class="sub">'+esc(e.Lugar||e.Modalidad||"")+(e.Responsable?' · responsable '+esc(pxUN(e.Responsable)):'')+(inv.length?' · '+inv.length+' invitaciones, '+si+' confirmadas':'')+'</span>';
    if(pxCalInvited(e)&&e.Estado==="Programada"){const r=R[PX.user.ID];extra+='<span class="calrsvp">'+(r?'Su respuesta: <strong>'+(r==="Sí"?"asistirá":"no asistirá")+'</strong> · ':'')+'<button type="button" class="btn sm'+(r==="Sí"?" primary":"")+'" data-p="rsvp|'+e.ID+'|Sí">Asistiré</button><button type="button" class="btn sm" data-p="rsvp|'+e.ID+'|No">No asistiré</button></span>';}}
  else extra='<span class="sub">'+esc(e.Nota||"")+'</span>';
  return'<div class="calrow '+cls+'"><span class="mono calh">'+(e.HoraInicio?esc(pxCalHora(e)):"todo el día")+'</span><div><button type="button" class="lnk calt" data-p="cev|'+e.src+'|'+e.ID+'">'+esc(e.Titulo)+'</button> <span class="tag">'+esc(e.Tipo)+'</span>'+(e.Estado&&e.Estado!=="Programada"?' <span class="st '+(e.Estado==="Realizada"?"ok":e.Estado==="Cancelada"||e.Estado==="Vencido"?"bad":"warn")+'">'+esc(e.Estado)+'</span>':'')+extra+'</div></div>';}
function pxCalConflicts(o,selfId){const ppl=new Set([o.Responsable].concat(pxCalInv(o).filter(i=>i.startsWith("u:")).map(i=>i.slice(2))));if(!o.HoraInicio)return[];const ini=o.HoraInicio,fin=o.HoraFin||o.HoraInicio;
  return PX.book.cal.filter(e=>e.ID!==selfId&&e.Fecha===o.Fecha&&e.Estado!=="Cancelada"&&e.HoraInicio&&e.HoraInicio<fin&&(e.HoraFin||e.HoraInicio)>ini&&([e.Responsable].concat(pxCalInv(e).filter(i=>i.startsWith("u:")).map(i=>i.slice(2)))).some(u=>ppl.has(u)));}
function pxDlgCal(id,fecha,comId){const e=id?PX.book.cal.find(x=>x.ID===id):null;const c=comId?PX.book.com.find(x=>x.ID===comId):null;const inv=e?pxCalInv(e):[];
  const usr=PX.book.usr.filter(u=>u.Activo!=="NO");
  openDlg(e?"Editar actividad":"Nueva actividad",'<div class="form"><label class="f wide">Título<input type="text" id="ca_t" value="'+esc(e?e.Titulo:c?c.Nombre:"")+'"></label><label class="f">Tipo<select id="ca_ti">'+opt(CAL_TIPOS.map(t=>t[0]),e?e.Tipo:c?"Comité":"Reunión")+'</select></label><label class="f">Comité (si aplica)<select id="ca_co">'+opt(PX.book.com.filter(x=>x.Activo!=="NO").map(x=>[x.ID,x.Nombre]),e?e.Comite:c?c.ID:"","—")+'</select></label><label class="f">Fecha<input type="date" id="ca_f" value="'+esc(e?e.Fecha:fecha||pxToday())+'"></label><label class="f">Hora de inicio<input type="time" id="ca_hi" value="'+esc(e?e.HoraInicio:"08:00")+'"></label><label class="f">Hora de fin<input type="time" id="ca_hf" value="'+esc(e?e.HoraFin:"09:00")+'"></label><label class="f">Modalidad<select id="ca_m">'+opt(CAL_MOD,e?e.Modalidad:"Presencial")+'</select></label><label class="f">Lugar<input type="text" id="ca_l" value="'+esc(e?e.Lugar:"")+'" placeholder="Sala de juntas, sede…"></label><label class="f">Enlace (si es virtual)<input type="text" id="ca_en" value="'+esc(e?e.Enlace:"")+'"></label><label class="f">Responsable<select id="ca_r">'+opt(usr.map(u=>[u.ID,u.Nombre+" · "+u.Cargo]),e?e.Responsable:(c&&c.Responsable)||PX.user.ID)+'</select></label><label class="f">Programa<select id="ca_p">'+opt(PROGS.filter(p=>p.g!=="ges"||p.k==="sogcs").map(p=>[p.k,p.n]),e?e.Programa:c?"sogcs":"","Institucional")+'</select></label><label class="f">¿Quién la ve?<select id="ca_v">'+opt([["Todos","Todo el personal"],["Solo invitados","Solo responsable e invitados"]],e?e.Visibilidad:"Todos")+'</select></label>'+(e?'':'<label class="f">Repetir<select id="ca_rep">'+opt([["","No se repite"],["7","Cada semana"],["14","Cada dos semanas"],["m","Cada mes"]],"")+'</select></label><label class="f">Repetir hasta<input type="date" id="ca_rh"></label>')+'<label class="f wide">Agenda o descripción<textarea id="ca_d" rows="3">'+esc(e?e.Descripcion:"")+'</textarea></label></div>'+
   '<fieldset class="pxfs"><legend>Invitados</legend><p class="note" style="margin:0">Invite áreas completas o personas. Cada invitado puede confirmar su asistencia.</p><div class="calinv"><div><strong class="note">Áreas</strong>'+pxAreas().map(a=>'<label class="chk"><input type="checkbox" data-cinv="a:'+esc(a)+'"'+(inv.includes("a:"+a)?" checked":"")+'> '+esc(a)+'</label>').join("")+'</div><div><strong class="note">Personas</strong>'+usr.map(u=>'<label class="chk"><input type="checkbox" data-cinv="u:'+u.ID+'"'+(inv.includes("u:"+u.ID)?" checked":"")+'> '+esc(u.Nombre)+' <span class="sub" style="display:inline">· '+esc(u.Cargo)+'</span></label>').join("")+'</div></div></fieldset>'+
   '<label class="chk" style="font-size:14px"><input type="checkbox" id="ca_ms"'+(e?"":" checked")+'> '+(e?"Enviar a los invitados una notificación con los cambios":"Enviar citación a los invitados por Mensajes")+'</label><p class="note" id="ca_cf" style="color:var(--warn)"></p>',e?"Guardar cambios":"Agendar",()=>{
   const o={Titulo:$("ca_t").value.trim(),Tipo:$("ca_ti").value,Comite:$("ca_co").value,Fecha:$("ca_f").value,HoraInicio:$("ca_hi").value,HoraFin:$("ca_hf").value,Modalidad:$("ca_m").value,Lugar:$("ca_l").value.trim(),Enlace:$("ca_en").value.trim(),Responsable:$("ca_r").value,Programa:$("ca_p").value,Visibilidad:$("ca_v").value,Descripcion:$("ca_d").value.trim(),Invitados:[...document.querySelectorAll("[data-cinv]:checked")].map(x=>x.dataset.cinv).join(",")};
   if(o.Titulo.length<4)return"Escriba el título de la actividad.";if(!o.Fecha)return"Elija la fecha.";if(o.HoraFin&&o.HoraInicio&&o.HoraFin<=o.HoraInicio)return"La hora de fin debe ser posterior a la de inicio.";
   const cf=pxCalConflicts(o,e?e.ID:null);if(cf.length&&!DLG.cfOk){DLG.cfOk=true;return"Cruce de horario: "+cf.map(x=>x.Titulo+" ("+pxCalHora(x)+")").join(", ")+". Vuelva a tocar el botón para agendar de todas formas.";}
   const send=$("ca_ms").checked;let created=[];
   if(e){pxUpd("cal",e,o);created=[e];}
   else{const rep=$("ca_rep").value,hasta=$("ca_rh").value;const dates=[o.Fecha];if(rep){if(!hasta||hasta<=o.Fecha)return"Indique hasta qué fecha se repite.";let d=pdate(o.Fecha);for(let i=0;i<60;i++){d=rep==="m"?addMonths(d,1):addDays(d,+rep);if(iso(d)>hasta)break;dates.push(iso(d));}}
     const serie=dates.length>1?"SR-"+Date.now().toString(36):"";dates.forEach(f=>created.push(pxAdd("cal","CA-",Object.assign({},o,{Fecha:f,Estado:"Programada",Respuestas:"{}",Serie:serie,Nota:"",Creador:PX.user.ID,Registrado:pxNow()}))));}
   if(send&&created.length){const x=created[0];const inv=pxCalInv(x);inv.forEach(to=>{const r=pxAdd("msg","M-",{Hilo:"",FechaHora:pxNow(),De:PX.user.ID,Para:to,Tipo:"Citación",Prioridad:"Rutina",Asunto:(e?"Cambio en: ":"Citación: ")+x.Titulo+" · "+fd(pdate(x.Fecha))+(x.HoraInicio?" "+x.HoraInicio:""),Cuerpo:(e?"Se actualizó la actividad.\n":"Queda citado(a) a la siguiente actividad.\n")+"Fecha: "+fd(pdate(x.Fecha))+(created.length>1?" (y "+(created.length-1)+" fechas más de la serie)":"")+"\nHora: "+(pxCalHora(x)||"por definir")+"\nModalidad: "+x.Modalidad+(x.Lugar?"\nLugar: "+x.Lugar:"")+(x.Enlace?"\nEnlace: "+x.Enlace:"")+"\nResponsable: "+pxUN(x.Responsable)+(x.Descripcion?"\n\nAgenda:\n"+x.Descripcion:"")+"\n\nConfirme su asistencia en Calendario de actividades.",Paciente:"",Programa:x.Programa,Plazo:x.Fecha,Estado:"Enviado"});r.Hilo=r.ID;});}
   PX.ui.calm0=o.Fecha.slice(0,7);PX.ui.cald=o.Fecha;pxBar();pxRefresh();toast((e?"Actividad actualizada":created.length>1?created.length+" actividades agendadas":"Actividad agendada")+(send&&pxCalInv(created[0]).length?"; citación enviada a "+pxCalInv(created[0]).length+" destinatarios.":"."));});}
function pxDlgCalView(src,id){
  if(src==="cse"){const s=PX.book.cse.find(x=>x.ID===id);pxDlgSes(s.Comite,s.Periodo);return;}
  if(src==="cmp"){pxGo("sogcs","cmp");return;}
  const e=PX.book.cal.find(x=>x.ID===id);const R=pxCalResp(e);const inv=pxCalInv(e);
  const people=new Map();inv.forEach(i=>{if(i.startsWith("u:"))people.set(i.slice(2),"");else PX.book.usr.filter(u=>u.Area===i.slice(2)&&u.Activo!=="NO").forEach(u=>people.set(u.ID,i.slice(2)));});
  const ed=pxCalCanEdit(e);const invited=pxCalInvited(e);
  openDlg(e.Titulo,'<p class="note" style="margin:0"><span class="tag">'+esc(e.Tipo)+'</span> '+(e.Estado!=="Programada"?'<span class="st '+(e.Estado==="Realizada"?"ok":"bad")+'">'+esc(e.Estado)+'</span>':'')+'</p><div class="calinfo"><div><b>Fecha</b>'+esc(fd(pdate(e.Fecha)))+' · '+esc(pxCalHora(e)||"sin hora")+'</div><div><b>Modalidad</b>'+esc(e.Modalidad)+(e.Lugar?' · '+esc(e.Lugar):'')+(e.Enlace?'<br><span class="mono" style="font-size:12.5px;word-break:break-all">'+esc(e.Enlace)+'</span>':'')+'</div><div><b>Responsable</b>'+esc(pxUN(e.Responsable))+'</div><div><b>Programa</b>'+esc(PROG[e.Programa]?PROG[e.Programa].n:"Institucional")+'</div><div><b>Visible para</b>'+esc(e.Visibilidad==="Solo invitados"?"responsable e invitados":"todo el personal")+'</div>'+(e.Serie?'<div><b>Serie</b>se repite ('+PX.book.cal.filter(x=>x.Serie===e.Serie).length+' fechas)</div>':'')+'</div>'+(e.Descripcion?'<p style="margin:0;white-space:pre-line">'+esc(e.Descripcion)+'</p>':'')+
   '<div><h3 style="margin:8px 0 4px">Invitados ('+people.size+')</h3>'+(people.size?'<table class="mini"><tbody>'+[...people.entries()].map(([u,a])=>'<tr><td>'+esc(pxUN(u))+(a?'<span class="sub">por área '+esc(a)+'</span>':'')+'</td><td>'+(R[u]==="Sí"?'<span class="st ok">Asistirá</span>':R[u]==="No"?'<span class="st bad">No asistirá</span>':'<span class="st base">Sin respuesta</span>')+'</td></tr>').join("")+'</tbody></table>':'<p class="note">Sin invitados.</p>')+'</div>'+
   (e.Nota?'<p class="note"><strong>Nota:</strong> '+esc(e.Nota)+'</p>':'')+
   (ed&&e.Estado==="Programada"?'<label class="f">Nota de cierre o motivo (para marcar realizada o cancelar)<input type="text" id="cv_n"></label>':'')+
   '<div class="copyrow">'+(invited&&e.Estado==="Programada"?'<button type="button" class="btn primary" data-p="rsvp|'+e.ID+'|Sí">Asistiré</button><button type="button" class="btn" data-p="rsvp|'+e.ID+'|No">No asistiré</button>':'')+(ed?'<button type="button" class="btn" data-p="caledit|'+e.ID+'">Editar</button>'+(e.Estado==="Programada"?'<button type="button" class="btn" data-p="calst|'+e.ID+'|Realizada">Marcar realizada</button><button type="button" class="btn danger" data-p="calst|'+e.ID+'|Cancelada">Cancelar actividad</button>':''):'')+'</div>',"Cerrar",()=>{});
  const ok=$("dlgok");if(ok)ok.classList.remove("primary");const x=$("dlgx");if(x)x.hidden=true;}
function pxCalRsvp(id,v){const e=PX.book.cal.find(x=>x.ID===id);const R=pxCalResp(e);R[PX.user.ID]=v;pxUpd("cal",e,{Respuestas:JSON.stringify(R)});closeDlg();pxRefresh();toast(v==="Sí"?"Asistencia confirmada.":"Se registró que no asistirá. El responsable lo verá en la lista de invitados.");}
function pxCalSt(id,st){const e=PX.book.cal.find(x=>x.ID===id);const n=($("cv_n")||{}).value||"";if(st==="Cancelada"&&n.trim().length<4){toast("Escriba el motivo de la cancelación en la nota.");return;}
  pxUpd("cal",e,{Estado:st,Nota:n.trim()});if(st==="Cancelada")pxCalInv(e).forEach(to=>{const r=pxAdd("msg","M-",{Hilo:"",FechaHora:pxNow(),De:PX.user.ID,Para:to,Tipo:"Citación",Prioridad:"Prioritaria",Asunto:"Cancelada: "+e.Titulo+" · "+fd(pdate(e.Fecha)),Cuerpo:"La actividad fue cancelada. Motivo: "+n.trim(),Paciente:"",Programa:e.Programa,Plazo:"",Estado:"Enviado"});r.Hilo=r.ID;});
  closeDlg();pxBar();pxRefresh();toast(st==="Cancelada"?"Actividad cancelada; se avisó a los invitados.":"Actividad marcada como realizada."+(e.Comite?" Registre el acta en SOGCS.":""));}
function pxCalExp(){const base=pdate((PX.ui.calm0||ym(TODAY()))+"-01");const I=pxCalItems(iso(monthStart(base)),iso(monthEnd(base)));
  pxExport("Calendario_actividades_"+ym(base)+".xlsx",[["Actividades",I,[["Fecha",e=>e.Fecha],["Hora",e=>pxCalHora(e)],["Actividad",e=>e.Titulo],["Tipo",e=>e.Tipo],["Estado",e=>e.Estado],["Modalidad",e=>e.Modalidad||""],["Lugar",e=>e.Lugar||""],["Responsable",e=>e.Responsable?pxUN(e.Responsable):""],["Invitados",e=>e.src==="cal"?pxCalInv(e).map(pxParaTxt).join("; "):""],["Confirmados",e=>e.src==="cal"?Object.entries(pxCalResp(e)).filter(([,v])=>v==="Sí").map(([u])=>pxUN(u)).join("; "):""],["Programa",e=>PROG[e.Programa]?PROG[e.Programa].n:""],["Nota",e=>e.Nota||""]]]]);}
function pxCalHoy(){if(!PX.book||!PX.user)return[];const t=pxToday();return PX.book.cal.filter(e=>e.Fecha===t&&e.Estado==="Programada"&&pxCalMine(e)).sort((a,b)=>String(a.HoraInicio).localeCompare(String(b.HoraInicio)));}
function pxCalPend(){if(!PX.book||!PX.user)return[];const t=pxToday();return PX.book.cal.filter(e=>e.Fecha>=t&&e.Estado==="Programada"&&pxCalInvited(e)&&!pxCalResp(e)[PX.user.ID]);}

