/* La solicitud vive en el libro de Hemodiálisis (hoja SolicitudesLab) porque son pacientes de ese libro; el módulo la valida, marca muestras y carga resultados en Paraclínicos. */
function pxLabNeedHD(){return'<div class="panel empty">Cargue el libro de Hemodiálisis (o entre a la demostración) para ver su solicitud de laboratorio. Los demás programas se integrarán cuando tengan módulo.</div>';}
function pxLabOport(per){const H=pxHD();if(!H)return null;const{ms,me}=pxPer(per);const L=H.lab.filter(live).filter(l=>l.FechaToma>=ms&&l.FechaToma<=me&&l.Registrado&&!/calculado|importado/i.test(l.Metodo||""));const d=L.map(l=>{const r=pdate(String(l.Registrado).slice(0,10));return r?dayDiff(l.FechaToma,r):null;}).filter(x=>x!=null&&x>=0);return d.length?{n:d.length,avg:d.reduce((a,b)=>a+b,0)/d.length,max:Math.max(...d)}:null;}
function pxLabPend(){const H=pxHD();if(!H)return[];ensureIdx();const cur=ym(TODAY());return H.sol.filter(live).filter(r=>r.Mes<=cur&&r.Estado!=="No tomada"&&!solResult(r.Paciente,r.Examen,r.Mes)).sort((a,b)=>a.Mes.localeCompare(b.Mes)||a.Paciente.localeCompare(b.Paciente));}
function pxLab(){const sub=PX.ui.sub||"sol";const H=pxHD();
  let h='<div class="mhead"><div><p class="eyebrow">Servicio de apoyo</p><h2 class="mt">Laboratorio clínico</h2><p class="note" style="margin:3px 0 0">Solicitud mensual de los programas, muestras tomadas, carga de resultados y oportunidad. Hemodiálisis y VIH generan solicitudes; los demás programas se agregan cuando tengan módulo.</p></div></div><div class="seg" role="group">'+[["sol","Solicitud del mes · HD"],["vih","Solicitud del mes · VIH"],["res","Carga de resultados"],["pend","Pendientes y oportunidad"]].map(([k,l])=>'<button type="button" data-p="go|lab|'+k+'" aria-pressed="'+(sub===k)+'">'+l+'</button>').join("")+'</div>';
  if(sub==="vih")return h+(typeof VX!=="undefined"&&VX.book?vxSolView("lab"):'<div class="panel empty">Abra el libro del programa VIH (o la demostración) para ver su solicitud.</div>');
  if(!H)return h+pxLabNeedHD();ensureIdx();
  if(sub==="sol")return h+solView("lab");
  if(sub==="res")return h+'<div class="panel" style="display:grid;gap:10px">'+solCarga()+'</div>';
  const P=pxLabPend();const per=pxMes();const op=pxLabOport(per);
  h+='<div class="tiles"><div class="tile '+(P.length?"warn":"ok")+'"><span class="tv">'+P.length+'</span><span class="tl">exámenes solicitados sin resultado (mes en curso y anteriores)</span></div><div class="tile"><span class="tv">'+(op?f1(op.avg,1):"—")+'</span><span class="tl">días promedio entre la toma y la carga del resultado · '+esc(pxMesTxt(per))+(op?' · máximo '+op.max:'')+'</span></div></div>';
  const by={};P.forEach(r=>{const k=r.Mes+"|"+r.Paciente;(by[k]=by[k]||[]).push(r);});
  h+='<div class="panel tablebox" style="padding:0"><table><thead><tr><th>Mes</th><th>Paciente</th><th>Exámenes sin resultado</th><th>Estado</th></tr></thead><tbody>'+(Object.entries(by).map(([k,L])=>{const[m,pid]=k.split("|");const p=IDX.pac.get(pid);return'<tr><td class="mono">'+esc(m)+'</td><td><strong>'+esc(pid)+'</strong><span class="sub">'+esc(nombre(p))+'</span></td><td style="font-size:13px">'+L.map(r=>esc(EX[r.Examen]?EX[r.Examen].l:r.Examen)).join(", ")+'</td><td style="font-size:13px">'+[...new Set(L.map(r=>r.Estado))].map(esc).join(", ")+'</td></tr>';}).join("")||'<tr><td colspan="4" class="note">Sin pendientes.</td></tr>')+'</tbody></table></div><p class="note">La oportunidad se mide entre la fecha de toma y la fecha en que el resultado quedó registrado en el sistema; no incluye el Kt/V calculado ni lo importado.</p>';
  return h;}

