function pxProdBlob(){const v=pxCfg("prod_fin",null);return v&&v.salt&&v.iv&&v.ct?v:null;}
async function pxProdEncrypt(){const iv=crypto.getRandomValues(new Uint8Array(12));const ct=await crypto.subtle.encrypt({name:"AES-GCM",iv},PRODF.key,new TextEncoder().encode(JSON.stringify(PRODF.data)));pxSetCfg("prod_fin",{salt:PRODF.salt,iv:b64(iv),ct:b64(new Uint8Array(ct))});pxBookInfo();}
function pxProdLock(msg){const was=!!PRODF.key||(typeof ST!=="undefined"&&ST.fin&&ST.fin.key);PRODF.key=null;PRODF.data=null;PRODF.salt=null;clearTimeout(PRODF.t);try{finLock();}catch(e){}if(msg&&was)toast(msg);}
function pxProdArm(){clearTimeout(PRODF.t);PRODF.t=setTimeout(()=>{pxProdLock("Producción asistencial bloqueada por 10 minutos sin uso.");if(PX.view==="prod")pxRender();},600000);try{if(ST.fin&&ST.fin.key)finArm();}catch(e){}}
const pxProdOpen=()=>!!PRODF.key;
async function pxProdUnlock(){const pw=$("prpw").value;const m=$("prmsg");if(!pw)return;m.textContent="Verificando…";const pb=pxProdBlob();const H=pxHD();const fails=[];let ok=0;
  if(pb){const r=await finTry(pw,pb);if(r){ok++;PRODF.key=r.key;PRODF.salt=pb.salt;PRODF.data=r.data;PRODF.data.tarifas=PRODF.data.tarifas||[];}else fails.push("las tarifas de los programas");}
  if(H&&H.finBlob){const r=await finTry(pw,H.finBlob);if(r){ok++;ST.fin.key=r.key;ST.fin.salt=H.finBlob.salt;ST.fin.data=r.data;ST.fin.data.facturado=ST.fin.data.facturado||{};ST.fin.data.tarifas=ST.fin.data.tarifas||[];}else fails.push("la conciliación de hemodiálisis");}
  if(!ok){m.textContent="Clave incorrecta.";$("prpw").value="";$("prpw").focus();return;}
  if(!pb){const salt=crypto.getRandomValues(new Uint8Array(16));PRODF.salt=b64(salt);PRODF.key=await deriveKey(pw,salt);PRODF.data={tarifas:[],creado:pxNow(),por:PX.user.Usuario};await pxProdEncrypt();pxLog("CREA CLAVE","cfg","prod_fin","Tarifas de producción con la misma clave de la conciliación de HD");}
  if(H&&!H.finBlob){const salt=crypto.getRandomValues(new Uint8Array(16));ST.fin.salt=b64(salt);ST.fin.key=await deriveKey(pw,salt);ST.fin.data={tarifas:[],facturado:{},creado:nowTs(),por:ST.user};await finEncrypt();logW("CREA CLAVE","fin","Fin_cifrado","Desde Producción asistencial");changed();}
  if(fails.length)toast("La clave abrió una parte pero no "+fails.join(" ni ")+": los libros tienen claves distintas. Use «Cambiar clave» para unificarlas.");
  pxLog("DESBLOQUEA","cfg","prod_fin","");pxProdArm();pxRender();}
async function pxProdCreate(){const a=$("prp1").value,b=$("prp2").value;if(a.length<8){toast("La clave debe tener al menos 8 caracteres.");return;}if(a!==b){toast("Las dos claves no coinciden.");return;}
  const salt=crypto.getRandomValues(new Uint8Array(16));PRODF.salt=b64(salt);PRODF.key=await deriveKey(a,salt);PRODF.data={tarifas:[],creado:pxNow(),por:PX.user.Usuario};await pxProdEncrypt();
  const H=pxHD();if(H&&!H.finBlob){const s2=crypto.getRandomValues(new Uint8Array(16));ST.fin.salt=b64(s2);ST.fin.key=await deriveKey(a,s2);ST.fin.data={tarifas:[],facturado:{},creado:nowTs(),por:ST.user};await finEncrypt();changed();}
  pxLog("CREA CLAVE","cfg","prod_fin","");pxProdArm();pxRender();toast("Clave creada. Descargue el libro institucional"+(H?" y el de hemodiálisis":"")+" para conservarla.");}
function pxProdTarifa(prog,act,eps,fecha){const T=(PRODF.data&&PRODF.data.tarifas)||[];const d=fecha||pxToday();const c=T.filter(t=>t.prog===prog&&norm(t.act)===norm(act)&&(!t.eps||t.eps===eps)&&(!t.desde||t.desde<=d)).sort((a,b)=>(b.eps?1:0)-(a.eps?1:0)||String(b.desde||"").localeCompare(String(a.desde||"")));return c[0]||null;}
function pxProdRegs(per){return PX.book.prd.filter(r=>String(r.Fecha).startsWith(per));}
function pxProdHD(per){const H=pxHD();if(!H)return null;ensureIdx();const{ms,me}=pxPer(per);const by={};let tot=0;
  pacs().forEach(p=>{const S=sesIn(p,ms,me,"Realizada");if(!S.length)return;const e=p.EPS||"Sin EPS";const b=by[e]=by[e]||{ses:0,ext:0,pac:0,esp:null};b.ses+=S.length;b.ext+=S.filter(s=>s.Tipo==="Extra").length;b.pac++;tot+=S.length;});
  let C=null;if(ST.fin&&ST.fin.key){C=conciliar(per);C.rows.forEach(r=>{const e=r.p.EPS||"Sin EPS";if(!by[e])by[e]={ses:0,ext:0,pac:0,esp:null};by[e].esp=(by[e].esp||0)+(r.esp||0);});}
  return{by,tot,C};}
function pxProdResumen(per){const rows=[];const HD=pxProdHD(per);if(HD)Object.entries(HD.by).forEach(([e,b])=>rows.push({prog:"hd",eps:e,act:"Sesiones de hemodiálisis realizadas",cant:b.ses,val:b.esp,auto:true,nota:b.ext?b.ext+" extra":""}));
  if(typeof VX!=="undefined"&&VX.book)vxProdMes(per).forEach(r=>{const t=pxProdOpen()?pxProdTarifa("vih",r.act,r.eps,per+"-15"):null;rows.push({prog:"vih",eps:r.eps,act:r.act,cant:r.cant,val:pxProdOpen()?(t?r.cant*(num(t.valor)||0):0):null,sin:pxProdOpen()&&!t?r.cant:0,auto:true,nota:"paquete por paciente-mes con atención"});});
  const g={};pxProdRegs(per).filter(r=>r.Anulado!=="SI").forEach(r=>{const k=r.Programa+"|"+(r.EPS||"Sin EPS")+"|"+r.Actividad;const t=pxProdOpen()?pxProdTarifa(r.Programa,r.Actividad,r.EPS,r.Fecha):null;const x=g[k]=g[k]||{prog:r.Programa,eps:r.EPS||"Sin EPS",act:r.Actividad,cant:0,val:pxProdOpen()?0:null,sin:0};x.cant+=num(r.Cantidad)||0;if(pxProdOpen()){if(t)x.val+=(num(r.Cantidad)||0)*(num(t.valor)||0);else x.sin+=num(r.Cantidad)||0;}});
  Object.values(g).forEach(x=>rows.push(x));return rows.sort((a,b)=>String(PROG[a.prog]?PROG[a.prog].n:a.prog).localeCompare(PROG[b.prog]?PROG[b.prog].n:b.prog)||a.eps.localeCompare(b.eps));}
function pxProd(){const sub=PX.ui.sub||"res";const per=pxMes();const open=pxProdOpen();const H=pxHD();
  let h='<div class="mhead"><div><p class="eyebrow">Gestión</p><h2 class="mt">Producción asistencial</h2><p class="note" style="margin:3px 0 0">Atenciones de todos los programas por mes y EPS. Hemodiálisis se calcula sola desde el turno; los demás programas registran sus atenciones aquí mientras no tengan módulo. Tarifas y valores, solo con la clave.</p></div><div class="copyrow">'+pxPerSel()+(open?'<button type="button" class="btn danger" data-p="prodlock">Bloquear valores</button>':'')+'<button type="button" class="btn" data-p="prodexp">Exportar el mes</button></div></div>';
  h+='<div class="seg" role="group">'+[["res","Resumen del mes"],["reg","Registro de atenciones"],["tar","Tarifas"],["hd","Hemodiálisis · conciliación"]].map(([k,l])=>'<button type="button" data-p="go|prod|'+k+'" aria-pressed="'+(sub===k)+'">'+((k==="tar"||k==="hd")&&!open?LOCK:"")+l+'</button>').join("")+'</div>';
  if(sub==="res"){const R=pxProdResumen(per);const tc=R.reduce((a,r)=>a+r.cant,0),tv=R.reduce((a,r)=>a+(r.val||0),0);const prg=new Set(R.map(r=>r.prog));
    h+='<div class="tiles"><div class="tile"><span class="tv">'+tc.toLocaleString("es-CO")+'</span><span class="tl">atenciones en '+esc(pxMesTxt(per))+' · '+prg.size+' programas</span></div><div class="tile"><span class="tv">'+(open?money(tv):"—")+'</span><span class="tl">'+(open?"valor según tarifas (hemodiálisis: esperado por contrato)":"valores bloqueados: ingrese la clave en Tarifas")+'</span></div><div class="tile '+(R.some(r=>r.sin)?"warn":"ok")+'"><span class="tv">'+(open?R.reduce((a,r)=>a+(r.sin||0),0):"—")+'</span><span class="tl">atenciones sin tarifa cargada</span></div></div>';
    if(!H)h+='<div class="alert warn"><p>Sin libro de hemodiálisis cargado: sus sesiones no aparecen en el resumen.</p></div>';
    h+='<div class="panel tablebox" style="padding:0"><table><thead><tr><th>Programa</th><th>EPS</th><th>Actividad</th><th class="num">Cantidad</th><th class="num">Valor</th><th>Fuente</th></tr></thead><tbody>'+(R.map(r=>'<tr><td>'+esc(PROG[r.prog]?PROG[r.prog].n:r.prog)+'</td><td>'+esc(r.eps)+'</td><td>'+esc(r.act)+(r.nota?'<span class="sub">'+esc(r.nota)+'</span>':'')+'</td><td class="num">'+r.cant.toLocaleString("es-CO")+'</td><td class="num">'+(open?(r.val!=null?money(r.val):"—")+(r.sin?'<span class="sub" style="color:var(--warn)">'+r.sin+' sin tarifa</span>':''):'<span class="sd">bloqueado</span>')+'</td><td><span class="tag '+(r.auto?"cac":"inst")+'">'+(r.auto?(r.prog==="vih"?"Agenda VIH":"Turno de HD"):"Registro manual")+'</span></td></tr>').join("")||'<tr><td colspan="6" class="note">Sin atenciones en el mes.</td></tr>')+'</tbody></table></div><p class="note">Hemodiálisis: sesiones realizadas del mes (programadas, extra y reprogramadas) contadas desde el turno; con la clave, el valor es el esperado según el contrato de cada EPS (paquete o por sesión). Los demás programas: cantidad × tarifa vigente del programa, actividad y EPS.</p>';return h;}
  if(sub==="reg"){const L=pxProdRegs(per).slice().sort((a,b)=>String(b.Fecha).localeCompare(String(a.Fecha)));
    h+='<div class="panel"><h3>Registrar atenciones</h3><div class="form"><label class="f">Fecha<input type="date" id="pr_f" value="'+pxToday()+'"></label><label class="f">Programa<select id="pr_p">'+opt(PROGS.filter(p=>(p.g==="mis"||p.g==="apo")&&p.k!=="hd"&&!(p.k==="vih"&&typeof VX!=="undefined"&&VX.book)).map(p=>[p.k,p.n]),PX.ui.prp||"nefro")+'</select></label><label class="f">EPS<select id="pr_e">'+opt(typeof epsList==="function"?epsList():["OTRA"],PX.ui.pre||"")+'</select></label><label class="f" style="grid-column:span 2">Actividad<input type="text" id="pr_a" list="pr_al"><datalist id="pr_al">'+pxProdActs(PX.ui.prp||"nefro").map(a=>'<option value="'+esc(a)+'">').join("")+'</datalist></label><label class="f">Cantidad<input type="number" id="pr_c" min="1" value="1"></label><label class="f">Código CUPS (opcional)<input type="text" id="pr_cu" placeholder="según el contrato"></label><label class="f">Paciente (ID, opcional)<input type="text" id="pr_pa"></label><label class="f wide">Nota<input type="text" id="pr_n"></label></div><div class="copyrow" style="margin-top:8px"><button type="button" class="btn primary" data-p="prodadd">Registrar</button><span class="note">Una línea puede ser una atención o el total del día de una actividad. Hemodiálisis no se registra aquí: sale del turno.</span></div></div>';
    h+='<div class="panel tablebox" style="padding:0"><table><thead><tr><th>Fecha</th><th>Programa</th><th>EPS</th><th>Actividad</th><th class="num">Cant.</th><th>Paciente</th><th>Registró</th><th></th></tr></thead><tbody>'+(L.map(r=>'<tr class="'+(r.Anulado==="SI"?"anul":"")+'"><td class="mono">'+pxFD(r.Fecha)+'</td><td>'+esc(PROG[r.Programa]?PROG[r.Programa].n:r.Programa)+'</td><td>'+esc(r.EPS)+'</td><td>'+esc(r.Actividad)+(r.CUPS?'<span class="sub">CUPS '+esc(r.CUPS)+'</span>':'')+(r.Nota?'<span class="sub">'+esc(r.Nota)+'</span>':'')+'</td><td class="num">'+esc(r.Cantidad)+'</td><td>'+esc(r.Paciente||"")+'</td><td><span class="sub">'+esc(r.Usuario)+'</span></td><td>'+(r.Anulado==="SI"?'<span class="sub">Anulado: '+esc(r.MotivoAnulacion||"")+'</span>':'<button type="button" class="lnk" data-p="prodan|'+r.ID+'">Anular</button>')+'</td></tr>').join("")||'<tr><td colspan="8" class="note">Sin registros en '+esc(pxMesTxt(per))+'.</td></tr>')+'</tbody></table></div>';return h;}
  if(!open)return h+pxProdLockView();
  if(sub==="tar"){const T=PRODF.data.tarifas;
    h+='<div class="panel"><div class="mhead"><h3 style="margin:0">Tarifas por programa, actividad y EPS</h3><div class="copyrow"><button type="button" class="btn sm" data-p="prodtadd">Agregar tarifa</button><button type="button" class="btn sm primary" data-p="prodtsave">Guardar cifrado</button><button type="button" class="btn sm" data-p="prodclave">Cambiar clave</button></div></div><p class="note">Copie los valores del contrato vigente; no hay valores precargados fuera de la demostración. EPS vacía = aplica a cualquier EPS. «Desde» permite conservar tarifas anteriores. Las tarifas de hemodiálisis (paquete, sesión, mínimo y máximo) están en la pestaña de conciliación.</p><div class="tablebox"><table><thead><tr><th>Programa</th><th>Actividad</th><th>CUPS</th><th>EPS</th><th>Valor</th><th>Desde</th><th></th></tr></thead><tbody>'+
     (T.map((t,i)=>'<tr><td><select data-prt="'+i+'|prog">'+opt(PROGS.filter(p=>(p.g==="mis"||p.g==="apo")&&p.k!=="hd").map(p=>[p.k,p.n]),t.prog)+'</select></td><td><input type="text" data-prt="'+i+'|act" value="'+esc(t.act||"")+'" list="pr_al'+i+'"><datalist id="pr_al'+i+'">'+pxProdActs(t.prog).map(a=>'<option value="'+esc(a)+'">').join("")+'</datalist></td><td><input type="text" data-prt="'+i+'|cups" value="'+esc(t.cups||"")+'" style="width:100px"></td><td><select data-prt="'+i+'|eps">'+opt(typeof epsList==="function"?epsList():[],t.eps||"","Cualquiera")+'</select></td><td><input type="text" inputmode="numeric" data-prt="'+i+'|valor" value="'+(t.valor??"")+'" style="width:120px"></td><td><input type="date" data-prt="'+i+'|desde" value="'+esc(t.desde||"")+'"></td><td><button type="button" class="lnk" data-p="prodtdel|'+i+'">Quitar</button></td></tr>').join("")||'<tr><td colspan="7" class="note">Sin tarifas cargadas.</td></tr>')+'</tbody></table></div></div>';return h;}
  if(!H)return h+'<div class="panel empty">Cargue el libro de Hemodiálisis para ver su conciliación.</div>';
  return h+vFin(true);}
function pxProdLockView(){const pb=pxProdBlob();const H=pxHD();const any=pb||(H&&H.finBlob);
  if(!any)return'<div class="panel lock"><h3>Crear la clave de Producción asistencial</h3><p class="note">Cifra las tarifas y valores de todos los programas y la conciliación de hemodiálisis. No se puede recuperar: guárdela donde guarda sus otras claves.</p><label class="f">Clave (8 caracteres o más)<input type="password" id="prp1" autocomplete="new-password"></label><label class="f">Repita la clave<input type="password" id="prp2" autocomplete="new-password"></label><button type="button" class="btn primary" data-p="prodcreate" style="justify-self:start">Crear clave y cifrar</button></div>';
  return'<form class="panel lock" id="prodf" onsubmit="return false"><h3>Ingrese la clave</h3><p class="note">Abre las tarifas de los programas'+(H&&H.finBlob?' y la conciliación de hemodiálisis':'')+'. Se bloquea sola al salir del módulo o tras 10 minutos sin uso.</p><label class="f">Clave<input type="password" id="prpw" autocomplete="current-password"></label><button type="submit" class="btn primary" style="justify-self:start">Desbloquear</button><p class="note" id="prmsg"></p></form>';}
function pxProdActs(prog){const s=new Set(PROD_ACT[prog]||[]);((PRODF.data&&PRODF.data.tarifas)||[]).filter(t=>t.prog===prog&&t.act).forEach(t=>s.add(t.act));PX.book.prd.filter(r=>r.Programa===prog&&r.Actividad).forEach(r=>s.add(r.Actividad));return[...s];}
function pxProdRead(){if(!PRODF.data)return;document.querySelectorAll("[data-prt]").forEach(el=>{const[i,f]=el.dataset.prt.split("|");const t=PRODF.data.tarifas[+i];if(!t)return;t[f]=f==="valor"?num(el.value):el.value.trim();});}
async function pxProdSave(){pxProdRead();const T=PRODF.data.tarifas;const bad=T.filter(t=>!t.prog||!t.act||num(t.valor)==null);if(bad.length){toast("Cada tarifa necesita programa, actividad y valor.");return;}await pxProdEncrypt();pxLog("MODIFICA","cfg","prod_fin","Tarifas (contenido cifrado)");pxProdArm();pxRender();toast("Tarifas guardadas y cifradas. Descargue el libro institucional.");}
function pxProdAdd(){const g=id=>($(id)||{}).value||"";const f=g("pr_f"),p=g("pr_p"),e=g("pr_e"),a=g("pr_a").trim(),c=num(g("pr_c"));if(!f||f>pxToday()){toast("Revise la fecha.");return;}if(!a){toast("Escriba la actividad.");return;}if(!c||c<1||c>5000){toast("La cantidad debe estar entre 1 y 5.000.");return;}
  PX.ui.prp=p;PX.ui.pre=e;pxAdd("prd","PR-",{Fecha:f,Programa:p,EPS:e,Paciente:g("pr_pa").trim(),Actividad:a,CUPS:g("pr_cu").trim(),Cantidad:c,Nota:g("pr_n").trim(),Registrado:pxNow()});pxRender();toast("Atención registrada.");}
function pxProdAnular(id){const r=PX.book.prd.find(x=>x.ID===id);openDlg("Anular registro "+id,'<p class="note">'+esc(r.Actividad)+' · '+esc(r.Cantidad)+' · '+pxFD(r.Fecha)+'. El registro no se borra: queda tachado con su motivo.</p><label class="f">Motivo<input type="text" id="pa_m"></label>',"Anular",()=>{const m=$("pa_m").value.trim();if(m.length<4)return"Escriba el motivo.";pxUpd("prd",r,{Anulado:"SI",MotivoAnulacion:m});pxRender();toast("Registro anulado.");});}
function pxProdClave(){openDlg("Cambiar clave de Producción asistencial",'<p class="note">Cambia la clave de las tarifas de los programas'+(pxHD()&&ST.fin.key?' y de la conciliación de hemodiálisis':'')+'.</p><label class="f">Clave nueva (8 caracteres o más)<input type="password" id="pk1" autocomplete="new-password"></label><label class="f">Repita la clave nueva<input type="password" id="pk2" autocomplete="new-password"></label>',"Cambiar",()=>{const a=$("pk1").value,b=$("pk2").value;if(a.length<8)return"Mínimo 8 caracteres.";if(a!==b)return"Las claves no coinciden.";
  (async()=>{pxProdRead();const s=crypto.getRandomValues(new Uint8Array(16));PRODF.salt=b64(s);PRODF.key=await deriveKey(a,s);await pxProdEncrypt();if(pxHD()&&ST.fin.key){finRead();const s2=crypto.getRandomValues(new Uint8Array(16));ST.fin.salt=b64(s2);ST.fin.key=await deriveKey(a,s2);await finEncrypt();logW("CAMBIA CLAVE","fin","Fin_cifrado","Desde Producción asistencial");changed();}pxLog("CAMBIA CLAVE","cfg","prod_fin","");toast("Clave cambiada. Descargue los libros.");pxRender();})();});}
function pxProdExp(){const per=pxMes();const R=pxProdResumen(per);const open=pxProdOpen();
  pxExport("Produccion_asistencial_"+per+".xlsx",[["Resumen",R,[["Programa",r=>PROG[r.prog]?PROG[r.prog].n:r.prog],["EPS",r=>r.eps],["Actividad",r=>r.act],["Cantidad",r=>r.cant],["Valor",r=>open&&r.val!=null?Math.round(r.val):""],["Sin tarifa",r=>open?r.sin||"":""],["Fuente",r=>r.auto?"Turno de hemodiálisis":"Registro manual"]]],
   ["Registros",pxProdRegs(per),[["ID",r=>r.ID],["Fecha",r=>r.Fecha],["Programa",r=>PROG[r.Programa]?PROG[r.Programa].n:r.Programa],["EPS",r=>r.EPS],["Actividad",r=>r.Actividad],["CUPS",r=>r.CUPS],["Cantidad",r=>r.Cantidad],["Paciente",r=>r.Paciente],["Nota",r=>r.Nota],["Anulado",r=>r.Anulado],["Motivo anulación",r=>r.MotivoAnulacion],["Registró",r=>r.Usuario]]]]);}

/* ================= v0.2 · Seguridad del paciente, IAAS y PROA con los datos de hemodiálisis ================= */
function pxSPHDCand(){const H=pxHD();if(!H)return[];ensureIdx();const reported=new Set(H.seg.filter(live).map(r=>r.Evento).filter(Boolean));const desde=addMonths(TODAY(),-6);
  return H.evt.filter(live).filter(e=>e.Fecha>=desde&&!reported.has(e.ID)&&(e.Severidad==="Severa"||["Caída","Error de medicación","Embolismo aéreo","Sangrado del acceso vascular",ITS].includes(e.Tipo))).sort((a,b)=>b.Fecha-a.Fecha);}
function pxSPHDBlock(){const C=pxSPHDCand();if(!pxHD())return"";
  return'<div class="panel"><div class="mhead"><h3 style="margin:0">Eventos de sesión de hemodiálisis por revisar ('+C.length+')</h3>'+(pxHD()?'<button type="button" class="btn sm" data-p="sphd|">Nuevo reporte de hemodiálisis</button>':'')+'</div><p class="note">Eventos severos, caídas, errores de medicación, embolismo, sangrado del acceso y bacteriemias registrados en el turno que aún no tienen reporte (últimos 6 meses).</p>'+(C.length?'<div class="tablebox"><table><tbody>'+C.map(e=>'<tr><td class="mono">'+fd(e.Fecha)+'</td><td>'+esc(e.Paciente)+'<span class="sub">'+esc(nombre(IDX.pac.get(e.Paciente)))+'</span></td><td>'+esc(e.Tipo)+'<span class="sub">'+esc(e.Severidad||"")+(e.Conducta?" · "+esc(e.Conducta):"")+'</span></td><td><button type="button" class="btn sm primary" data-p="sphd|'+e.ID+'">Reportar</button></td></tr>').join("")+'</tbody></table></div>':'<p class="note">Sin pendientes.</p>')+'</div>';}
function pxIAASHD(){if(!pxHD())return'<div class="panel empty">Cargue el libro de Hemodiálisis para confirmar sus infecciones.</div>';ensureIdx();
  return'<p class="note">Periodo de hemodiálisis: '+fd(ST.ps)+' a '+fd(ST.corte)+' (se cambia en la barra de Hemodiálisis). Aquí se confirman las bacteriemias con hemocultivo, microorganismo y resistencia; solo las confirmadas cuentan para IAAS-02 y para dia_33 de la CAC.</p>'+segIAAS();}

/* ================= v0.2 · ruta del paciente (Documentos y guías) ================= */
function pxRutaView(compact){const R=rutaGet();const e=rutaEstado();const ed=PX.user&&pxDocEdit();const D=PX.book?PX.book.doc:[];
  const link=code=>{const d=D.find(x=>x.Codigo===code);return d?'<span class="mono">'+esc(code)+'</span> '+pxDocLink(d):'<span class="mono">'+esc(code)+'</span>';};
  let h='<div class="panel" style="display:grid;gap:12px"><div class="mhead"><div><h3 style="margin:0">Ruta del paciente en hemodiálisis</h3><p class="note" style="margin:3px 0 0">Mensajes clave de cada etapa para el personal. Estado: <span class="tag '+(e==="Aprobada"?"cac":"inst")+'">'+esc(e)+'</span>. '+(e==="Aprobada"?"":"Es un borrador: el texto válido es el del documento controlado de cada etapa hasta que Calidad y Dirección Médica lo aprueben.")+'</p></div>'+(ed?'<div class="copyrow"><button type="button" class="btn sm" data-p="rutaedit">Editar la ruta</button></div>':'')+'</div>';
  h+='<div class="pxcards" style="grid-template-columns:repeat(auto-fill,minmax(280px,1fr))">'+R.map((s,i)=>'<div class="panel" style="display:grid;gap:6px;align-content:start;border-top:3px solid var(--accent)"><b style="font-family:var(--f-display)">'+(i+1)+'. '+esc(s.t)+'</b><ul style="margin:0;padding-left:18px;font-size:13.5px;display:grid;gap:3px">'+(compact?s.m.slice(0,3):s.m).map(x=>'<li>'+esc(x)+'</li>').join("")+(compact&&s.m.length>3?'<li class="sub">y '+(s.m.length-3)+' más</li>':'')+'</ul>'+(s.docs?'<span class="note">Documento: '+String(s.docs).split(",").map(c=>link(c.trim())).join(" · ")+'</span>':'')+'</div>').join("")+'</div></div>';
  return h;}
function pxDlgRuta(){const R=rutaGet();const e=rutaEstado();
  openDlg("Editar la ruta del paciente en hemodiálisis",'<p class="note">Un mensaje por línea. «Documento»: códigos del listado maestro separados por coma. La aprobación corresponde a Calidad y Dirección Médica.</p><label class="f">Estado<select id="ru_e">'+opt(["Borrador por validar","En revisión","Aprobada"],e)+'</select></label>'+R.map((s,i)=>'<fieldset class="pxfs"><legend>'+(i+1)+'. '+esc(s.t)+'</legend><label class="f">Título<input type="text" id="ru_t'+i+'" value="'+esc(s.t)+'"></label><label class="f">Mensajes<textarea id="ru_m'+i+'" rows="4">'+esc(s.m.join("\n"))+'</textarea></label><label class="f">Documento<input type="text" id="ru_d'+i+'" value="'+esc(s.docs||"")+'"></label></fieldset>').join("")+'<button type="button" class="lnk" data-p="rutareset">Volver al borrador original</button>',"Guardar",()=>{
    const N=R.map((s,i)=>Object.assign({},s,{t:$("ru_t"+i).value.trim()||s.t,m:$("ru_m"+i).value.split("\n").map(x=>x.trim()).filter(Boolean),docs:$("ru_d"+i).value.trim()}));if(N.some(s=>!s.m.length))return"Cada etapa necesita al menos un mensaje.";
    pxSetCfg("ruta_hd",N);pxSetCfg("ruta_hd_estado",$("ru_e").value);pxLog("MODIFICA","cfg","ruta_hd","Estado: "+$("ru_e").value);pxBookInfo();pxRender();toast("Ruta guardada en el libro institucional.");});}

